const A=(name:string,city:string,meta:string,detail:string,best:string):Item=>({name,city,meta,detail,best,source:checked});
export const attractions:Item[]=[
A('大皇宫 & 玉佛寺','曼谷','曼谷必看No.1：两百年王朝权力心脏＋泰国国宝玉佛，不看等于没来过；代价是人多、规矩严，至少留半天。小红书实测（2026-09-28 第12轮3篇专帖深读，正文+评论区+图片逐张翻验，证据见 hidden_files/xhs-coverage-bangkok.md 第12轮）：最佳游玩 08:30 到达避旅行团；门票约500泰铢（作者称），玉佛寺与大皇宫之间联票可在两处往返两次；玉佛寺正殿内禁止拍照（殿外可向内拍）；孔剧表演周一到周五 13:00/14:30/16:00；需遮肩膝（租借沙龙50泰铢）。避坑：小心"皇宫关闭"搭讪骗局、"冰沙20泰铢变800泰铢"、"去卧佛寺只能坐船（1000泰铢）"（步行5分钟即到）；出了大皇宫有免费摆渡车。','地址 Na Phra Lan Rd, Phra Nakhon；每日8:30–16:30（售票8:30–15:30），外国人500泰铢含玉佛寺与诗丽吉纺织博物馆；MRT Sanam Chai 步行约10分钟，或湄南河快船至 Tha Chang 码头；严格遮肩盖膝、禁紧身破洞透明衣物，入口可租借服饰；建议8:30到避旅行团，官网 royalgrandpalace.th；Google Maps 大皇宫 4.6 星（80,016 条评价）、玉佛寺 4.7 星（43,812 条评价）。','08:30到避团客；门票保留好，会再次验票。'),A('卧佛寺 Wat Pho','曼谷','大皇宫的完美下半场：46米卧佛看完、顺手在按摩发源地按个摩回血；别单独跑，绑着大皇宫一起逛才划算。小红书实测（2026-09-28 第12轮）：108个功德钵投币祈福很有仪式感；卧佛寺门票约300泰铢（评论样本）；卧佛寺旁 Tha Tien 码头坐船到郑王庙 5.5 泰铢；卧佛寺周边也有类似大皇宫的搭讪骗局。','地址 2 Thai Wang Rd（Sanam Chai Rd），Phra Nakhon 区（大皇宫以南，步行可串联）；每日8:00–18:30，外国人门票300泰铢；MRT Sanam Chai站或湄南河快船 Tha Tien码头即到，码头过江船5.5泰铢可接郑王庙；46米卧佛是正殿主角，殿内108个功德钵可逐个投币祈福；寺内设泰式按摩学校（按摩发源地），体验要留排队时间；全名 Wat Phra Chetuphon，Google Maps 4.7 星（38,138 条评价），官网 watpho.com；周边有"皇宫/寺庙关闭"类搭讪骗局，别理、别跟走。','留出按摩排队时间。'),A('郑王庙 Wat Arun','曼谷','曼谷的明信片本体：82米瓷塔，日落前登平台俯瞰湄南河，傍晚到对岸拍剪影；之后顺势过河去唐人街扫街，一天完美收官。小红书实测（2026-09-28 第12轮大皇宫专帖评论区）：郑王庙泰服租赁 150–200 泰铢/套，跟拍约 1400 泰铢。','地址 158 Thanon Wang Doem, Bangkok Yai 10600（全名 Wat Arun Ratchawararam）；每日8:00–18:00（末入场17:30），门票200泰铢/人；BTS Saphan Taksin转湄南河快船至Tha Tien码头、再坐过江轮渡约3分钟（卧佛寺旁同码头过江亦可）；严格着装、遮肩盖膝；只能登开放阶梯或平台、台阶陡，不写登顶，清晨或傍晚光线最佳；Google Maps 4.7 星（45,250 条评价）。','傍晚看河对岸剪影；小红书实测免费机位：谷歌导航"The Gate Bangkok"（328 Maha Rat Rd），小巷走到头即机位，亮灯后的金色佛塔+黄昏是最佳时刻；河对面有屋顶酒吧可远眺。'),A('湄南河游船','曼谷','它不是景点，是看懂曼谷的方式：傍晚坐船一次收完大皇宫、郑王庙的灯火剪影；但体验一次就够，别花钱坐两遍。小红书实测（bangkok-2026-09-13 §19）：郑王庙门票200泰铢，河对岸免费观景台看"橘子味夕阳"（导航Public View Point，步行约176m）；蓝旗船30-40泰铢（Rajinee码头上船，末班约18:40）；想看蓝调时刻坐18:00班次（Asiatique码头起点）、二楼左后方，1105赞帖称"花得最值的8块钱"；免费机位导航"The Gate Bangkok"（328 Maha Rat Rd）。','出发码头 ICONSIAM、Asiatique；日落船约17:00开、晚餐船约19:15–20:00开，航程1.5–2小时；日落船850泰铢起、晚餐船990–1,799泰铢；Asiatique 走 BTS Saphan Taksin 加 Sathorn 码头免费接驳船，ICONSIAM 走 BTS 转 Gold Line；网上提前订、提前45–60分钟到，多数24小时前免费取消；私人长尾船提前议价、穿救生衣。','傍晚坐，看蓝调时刻。'),A('恰图恰周末市场','曼谷','一年只有周末能逛的淘宝场：1.5万个摊位里藏着古董和设计师小店，服装比商场便宜30-50%；不爱逛街的直接跳过，想去的圈定目标区、两小时速战。交通：BTS Mo Chit / MRT Kamphaeng Phet。小红书避雷（§20）：门口面馆"吃了200多🐷给300不补钱"找零诈骗；周五很多铺关门，周末才全开。','地址 Kamphaeng Phet 2 Road, Chatuchak（JJ Market）；周六至周日9:00–18:00为核心时段、周五晚有批发场，免费入场；BTS Mo Chit 1/3号出口步行即达，或 MRT Chatuchak Park / Kamphaeng Phet 站；15,000+摊位可讲价，官网 chatuchakmarket.org；清晨去避暑与人流，注意防暑并看好财物。','清晨去，正午炎热拥挤；市场内可换汇/ATM取现（3万泰铢封顶）；印度棉服饰、鳄鱼皮包在gate23附近；仅周末全开、周中开得少；可砍价。'),A('吉姆·汤普森之家','曼谷','听故事来的地方：一个美国人如何救活泰国丝绸，配6栋百年柚木老屋；室内禁拍、讲解约45分钟，时间紧就舍掉，猎奇党会觉得值。','地址 6/1 Soi Kasemsan 2, Rama 1 Road, Pathumwan, Bangkok 10330（BTS National Stadium 1号口步行约5分钟，运河船 Hua Chang 码头约2分钟）；每日10:00–17:00（Art Center 开到18:00），成人250泰铢、10–21岁150泰铢（凭ID）、10岁以下免费，仅现场购票；主宅必须跟导览（泰/英/法/中/日，约30–45分钟，含票价），须脱鞋、大包存柜，全程预留约1.5小时，末场导览经常满位、建议早到；室内拍照新规为允许无闪光拍摄、禁闪光灯/视频/摆拍，老导游仍可能按旧规说禁拍，以现场导游要求为准。','按导览场次到。'),A('唐人街耀华力路','曼谷','曼谷夜晚最接地气的一条街：白天百年金店中药铺，入夜整条路霓虹扫街；就当逛吃氛围体验，别指望每家都好吃。小红书第50轮实测（2026-09-28，6帖转done）：夜市路边榴莲车380铢/盒现场开果（江小丫吖，310赞）；七彩芒果糯米饭超上镜；扫街机位：霓虹灯牌交错的老字号金铺/冒着锅气的路边炒粉摊/红灯笼下的潮州戏台；MRT龙莲寺站4号口出即到；建议晚上去，夜幕降临耀华力路变身"赛博朋克美食天堂"。','地址 Yaowarat Road, Samphanthawong；街头美食夜市约16:00起至深夜，免费逛、餐饮按摊位计价（人均无统一数据）；MRT Blue Line Wat Mangkon 站出口直达耀华力路，亦可经 MRT Hua Lamphong 前往；白天看百年金店与中药铺、入夜扫街吃夜市，餐饮评价分化、不称必吃圣地，按明码与排队情况现场挑。','分白天与晚间体验。'),A('Talat Noi ＋ 宋瓦路老街','曼谷','湄南河畔的老社区慢逛线：百年中式老宅、涂鸦巷与河景咖啡，傍晚光线最好；本程定版排 12-19 16:00–18:00，逛完接宋瓦路再步行去耀华力夜市，不用另订、不用门票。','定版傍晚段（2026-10-23 用户定版 PDF＋2026-10-24 定版落站，源见 cloudDayOverrides 12-19 时间线）：Talat Noi 在湄南河畔、唐人街一带——看点是百年中式老宅 So Heng Tai、涂鸦巷、老店与河景咖啡；再接宋瓦路（Song Wat）老街一带的老字号与街景。街区全天可逛、免费，餐饮与各店消费另计；各店具体营业时间与 So Heng Tai 参观口径未明确，临行用地图复核、不按某一家店的钟点锁死行程。动线：当天 16:00 从 Rosewood Bangkok 准时出门（下午先回酒店泳池＋Spa 休整，别泡到误了光线），慢慢逛约 2 小时，逛完步行约 10 分钟到耀华力唐人街接夜市扫街；从酒店前往的车程与方式帖级未明确，临行按地图打车／Grab 复核。穿好走的鞋、巷子窄处看好随身物品。','已定版（12-19 傍晚主线）：16:00–18:00 按光线走、不提前不拖晚；与耀华力夜市是同一晚连逛，不是二选一，更不另订 tour。'),A('伦披尼公园','曼谷','市中心"野生侏罗纪公园"：免费看巨蜥，日落时最活跃；住得近、想放空倒时差时去跑个步。','小红书实测（bangkok-2026-09-13 §26，8篇全推荐）：市中心免费看巨蜥（"0元看巨蜥也太酷了"506赞；"真的会为了伦披尼公园再来一次曼谷"）；巨蜥18:00-19:00日落时最活跃（白天怕热）；别投喂别靠近。地址Rama IV路124号，每日4:30–22:00免费开放；MRT Lumphini／Silom站或BTS Sala Daeng站步行即达；园内约57公顷、2.5公里跑道，湖上可免费划船约15分钟（限重75公斤、工作人员可能先称重）；建议下午4点后到，一趟赶上划船与巨蜥活跃时段；园里流浪猫多且亲人。','日落前去（18:00-19:00巨蜥最活跃）。'),A('ICONSIAM','曼谷','硬件顶级的河畔商场，但3天行程里优先级不高：购物不如暹罗、河景坐船已看过；住得近就来吹江风吃个饭，不必专门腾半天。','与暹罗商圈功能不同，不做二选一。小红书实测（§24，2874赞帖）："来曼谷只逛一个商场选它"，室内水上市场+奢侈品+美食+夜景一站式，营业10:00-22:00。避雷：BTS Saphan Taksin转免费接驳船问清方向；人多，预留半天。严格重做8篇口碑分化（2推／5避雷／1中性，§24）：连避雷帖也认可G层SookSiam室内水上市场；槽点是体量大、楼层绕、电梯难找，散场打车极难。交通以BTS Krung Thon Buri转Gold Line至Charoen Nakhon站天桥直达最稳，别只靠接驳船；折扣与美食区评价不如Siam Paragon，冲购物别抱太高预期。','河畔日单独安排。'),A('四面佛','曼谷','不占时间的顺路神：就在暹罗商圈路口，逛街路过花15分钟拜一圈、看看还愿的传统舞；别为它单独规划行程。','地址 494 Ratchadamri Rd（Grand Hyatt Erawan 旁）；BTS Chit Lom 站天桥直达、步行约3–5分钟；每日约6:00–22:00（部分来源至23:00），免费参拜；供品约25泰铢起、顺时针参拜四面，300泰铢祈福套装与还愿舞260泰铢起、先问清价格再买；周四夜晚最旺、高峰约18:00–20:00、周日人流爆满，想清净避开这两个时段；Google Maps 4.7星、7,002条评价，评价称氛围平和热闹；周边小贩价格不一，不必在路边摊高价买供品。','与暹罗/奇隆顺路；拜法顺时针、报姓名生日愿望并按许愿时说的方式还愿；禁忌偏心、食言、穿露肩装；人多时可去金山寺/王孙寺避人潮。'),A('金山寺','曼谷','78米人造金山：曼谷最高寺庙，"不浮夸"的小众日落机位；下午还有体力就来，累瘫了舍掉也不可惜。','78米人造金山、曼谷最高寺庙，约200年历史、佛塔内供奉释迦牟尼佛舍利；360度老城全景＋人少安静。避雷：门票已从50涨到100泰铢（两帖评论确认）；阶数来源不一，不使用343级精确说法。位置在老城区东北侧、近Ratchadamnoen大道（Pom Prap Sattru Phai区）；每日8:00–17:00；无直达轨交，MRT Sam Yot或Hua Lamphong下车步行20–30分钟、或打车5–10分钟，也可坐Khlong Saen Saep运河船到Phan Fa Lilat码头步行约10分钟；着装遮肩盖膝，清晨或傍晚光线最佳，11月水灯节期间有庙会。','傍晚登高。'),A('Mahanakhon 天空步道','曼谷','曼谷最高处的付费刺激：310米玻璃栈道悬空看夜景；但它和金山寺的免费日落是二选一，恐高或预算紧直接舍，不亏。','小红书实测（§23，推荐7/避雷1/中性0）：310米玻璃栈道"真的会腿软"；营业10:00-19:00（最迟18:30入场）；4-5PM来一次看完白天+日落+夜景；现场价1080-1200泰铢，找代理买折扣票（约100元）；恐高慎上玻璃地板。0元替代机位：对面Empire Tower 55楼的%Arabica，点杯咖啡同款视角。地址 King Power Mahanakhon, 114 Narathiwas Road, Silom, Bang Rak；BTS Chong Nonsi（Silom线S3）3号出口沿Narathiwas路步行约5分钟。门票另一售票口径：成人约880泰铢（含72层室内观景+74层室外+玻璃栈道）、日落票含照片约1,100泰铢起、100cm以下免费，与上方小红书现场价口径不一致，行前以官网为准；同源另记每日10:00–24:00、末入场23:00，与小红书实测的19:00收场口径冲突，同样行前核官网。314米为曼谷最高楼，77层屋顶酒吧约17:00–24:00；建议提前订定时票、周末易售罄，大风暴雨时玻璃栈道关闭。','晴天4-5PM到，一次看完白天+日落+夜景。'),
A('大城府 Ayutthaya 古城遗迹','曼谷','曼谷周边最值得的一日游：417年古都、世界遗产，泰国历史的源头；但它吃掉一整天，第一次来只有3天就忍痛舍，留给下次。','UNESCO世界遗产，曼谷以北约80公里；寺庙每日约8:00–18:00（以现场公告为准）。三大王牌寺庙：玛哈泰寺（树抱佛头）80泰铢、柴瓦塔那兰寺80泰铢（部分区域修缮中）、崖差蒙空寺20–40泰铢（86版西游记取景地、可登塔俯瞰），另有42米卧佛的大城府卧佛寺免费；票价有涨价记录、行前核对。交通：邦苏中央车站（Krung Thep Aphiwat，别去老华南蓬站）火车单程15–20泰铢约1–1.5小时，历史公园在火车站河对岸约4公里需坐tuk-tuk，城内各寺相距2–3公里可用Grab或租摩托，包车样本约519元（7座）；建议下午4点后看日落。吃：巴莱船面Pa Lek Boat Noodle（米其林必比登）约20泰铢/碗。进寺遮肩盖膝、不穿无袖；车站假工作人员戴绿色牌谎称火车不便推销高价包车，真工作人员是红色胸牌、只在售票点前引导。','邦苏火车站单程15–20泰铢，或包车一日；车站自称工作人员的拉客属骗局（2026-09-13小红书严格重做结论）。'),A('丹嫩沙多水上市场+美功铁道','曼谷','经典但期望要管好：水上市场偏游客版，美功铁道只有火车贴身而过的三分钟奇观；和大城府只能二选一，我站大城府。','距曼谷约70公里，两处相距约20分钟车程，打包一日游约3–4小时（严格重做10篇：推荐2/避雷4/避坑指南4）；美功火车进站样本08:30/11:10/14:30/17:40、出站06:20/09:00/11:30/15:30（行前再核），贴身而过是核心体验、注意安全，铁道中段商铺有强制消费、往人少那边走物价更低；丹嫩沙多样本08:00–16:00（下午1点后摊位陆续撤离），手摇船约400铢/船（约40分钟、船上买船上吃）、电动船开价1000铢/人可讲价至300–500铢，黑码头开价4000铢/人须避开；差评集中在船夫关发动机逼消费、水脏有异味、东西贵且重复，评论多推荐更本地的空叻玛荣（Khlong Lat Mayom）替代。','让司机直接开进市场里面；工作日上午去避周末堵船。'),
A('双龙寺','清迈','清迈只能去一座寺就选它：白象驮舍利的600年传说、供奉佛骨的金塔、俯瞰全城的观景台，历史风景一次给齐。','素贴山顶，古城以西约15公里、海拔约1,073米，车程约30–45分钟；每日约6:00–18:00（部分来源称至20:00、无官网以现场为准），外国人门票约30泰铢、缆车约50泰铢；红色双条车单程约40–60泰铢（动物园/Huay Kaew路一带拼车）或 Grab/包车；登309级那伽阶梯或坐缆车，遮肩盖膝、上层平台脱鞋、入口可借纱笼，清晨到避团，可串 Wat Pha Lat。','清晨或日出优先；小红书10帖严格重验（6推/1中/1不推荐，2026-09-19落盘）：金塔反光强、必备防晒+墨镜，脱鞋区地板烫建议穿袜子；上午或傍晚光线柔和人少；300+级那伽阶梯有电梯/室内缆车（20–50铢）；门票约30铢；双条车山路颠簸，晕车者慎乘；寺庙旁华夫饼/饭摊位被实测态度差且不找零（135铢付150不找钱）避开；观景台小路旁民居有野狗包抄，别靠近独栋民居。'),A('帕拉特寺 Wat Pha Lat','清迈','上素贴山半路的森林古寺：藏在林子里的苔藓石塔、小瀑布与俯瞰清迈的观景台，游客少、安静——本程定版排 12-16 傍晚，上双龙寺看日落前先停这一站。','素贴山上山路半途（古城以西、往双龙寺方向），森林环绕的古寺：苔藓覆盖的石塔与佛像、小瀑布、能俯瞰清迈城的观景台，氛围安静、游客明显比双龙寺少。开放以寺庙官方脸书口径每日 6:00–17:30 为准（多个 2026 指南写约至 18:00）——傍晚去务必按 17:30 关门倒排：最晚 16:45 前到、停 30–45 分钟即走，接着上双龙寺赶 12 月约 17:50 的日落。免费入场；另一条走 Monk\'s Trail 徒步上山的路线另有 ฿100 步道费口径，乘车从公路进不涉及。交通：随上双龙寺的包车／Grab／双条车顺路停，不单独专程；着装遮肩盖膝。证据：hidden_files/tour-research/phuket-charter-and-checks-2026-10-24.md（2026-10-24 查证）。','已定版（12-16 傍晚顺路站）：只作双龙寺日落线的前站、按 17:30 关门倒排时间，不单独成行；当天泰拳课若延误，先保这条素贴山线。'),A('契迪龙寺','清迈','残缺的大塔比完整的更有故事：600年兰纳兴衰都写在塔身上；和帕辛寺步行可达，顺路一起看。','地址 103 Prapokklao Road, Si Phum, Mueang Chiang Mai 50200，14 世纪佛塔遗址，位于古城中心；参观区每日约 6:00–18:00（寺院大院开放更晚，按 6:00–18:00 规划更稳妥），外国人约 50 泰铢/成人、20 泰铢/儿童（各来源 40–50 泰铢浮动、只收现金，以现场为准），着装遮肩过膝、入殿脱鞋，入口可借纱笼；古城内步行可达，古城外乘双条车/tuk-tuk/Grab。清晨 6:00–9:00 光线好、人少；与帕辛寺步行约 10 分钟串联，周日傍晚可顺路接 Ratchadamnoen 路周日步行街。','清晨或傍晚；小红书10帖严格重验（5推/2中/3不推荐，2026-09-19落盘）：城市柱神殿女性禁入是核心争议（两帖因此判不推荐），去前想好；门票约50铢、只收现金；晚上约22:00关门，关门前20分钟工作人员基本不管（仍提倡购票进入）；清晨可赶上大殿群僧早课，念经声有禅意。'),A('帕辛寺','清迈','为兰纳古壁画和帕辛佛来的一座活着的古寺；和契迪龙寺步行可达，顺路进去坐十分钟，值。','地址 2 Sam Lan Road, Si Phum, Chiang Mai 50200，古城西端，塔佩门沿 Ratchadamnoen 路向西约 1.2 公里（步行约 15 分钟），古城外可乘双条车/tuk-tuk/Grab；每日约 6:00–17:00（大院可至黄昏），外国人约 20–40 泰铢（Lai Kham 小堂约 40 泰铢），着装遮肩过膝、入殿脱鞋，门口可借纱笼。必看 Viharn Lai Kham 小堂内 19 世纪兰纳壁画（描绘兰纳日常生活，是付小额门票的核心理由）；早 7:00–9:00 光线好、人少，与契迪龙寺步行约 10 分钟串联。','与契迪龙寺同线；小红书4帖帕辛寺（3推/1不推荐）：周日清晨门口有Tak Bat布施体验（面包牛奶水果约18份，门口711可买）；"清迈必打卡"，位置在古城西端/周日夜市尽头，着装过膝不露肩，下午4点左右去、夕阳洒在金塔上最美；付费正殿50铢实测"进去不到一分钟"，只逛免费外围也足够。'),A('因他农国家公园','清迈','泰国最高峰加云雾林很美，但要掏出完整的一整天，对清迈两天的行程杀伤力太大；没有登顶执念就果断舍。','地址：清迈西南约 120 公里，最高峰海拔 2,565 米（泰国最高峰）；公园每日约 5:30–18:30（各来源开门 5:00–6:00 不一，小红书团多按 08:00–16:30 入园，以所报团／现场为准）。外国人门票 300 泰铢／成人、150 泰铢／儿童（3–14 岁），自驾汽车另收 30 泰铢，皇家双塔另收 100 泰铢／人。交通最省心是报清迈出发一日游（含酒店接送），自驾单程约 2 小时，公共双条车需换乘 2.5–3 小时以上不推荐；山上景点分散、步行不现实。Kew Mae Pan 步道每年 6–10 月关闭、旺季名额有限早到；山顶最低约 5℃，带保暖衣、雨具与合脚鞋，避开宋干节等长假堵车。12 月山上较凉，行前核对天气。','可跳过（判定：整日量级，让位大象自然公园与烹饪课；以下为去了才用的实测要点）。选择含双塔与瀑布的正规团；小红书10帖严格重验（9推/1中，2026-09-19落盘）：门票300B/人、K线向导200B（环线2.8km约2h、9月关闭、11月至次年5月开）/P线向导220B（2.6km约3h、瀑布多新手友好、雨季只开P线、起点终点不在一处），向导强制、入口随机分配无需预约；公园08:00–16:30、市区车程1.5–2h；山上最冷约12度（9月约18–19℃），带薄外套+冲锋衣（高海拔会突然下暴雨）；一日团约250–300元/人含接送门票午餐（飞猪/携程可报）；中立派"去一次就好"（远、价格不低）；票根保管好一路查票，国王塔王后塔另收费，山顶小卖部贵。'),A('大象自然公园','清迈','在意动物福利就别犹豫：不骑不看表演，和年长救援象安静相处半天，是清迈最有分量的半天。','清迈以北约60公里Mae Taeng山谷、车程约90分钟，不可自行前往、必须先在官网或塔佩门附近市区办公室预订项目，每日限流、建议提前1–3周订；半日游上午场约7:30–8:00、下午场约12:00从酒店接客，官网价半日2,500泰铢（3–11岁儿童半价、0–2岁25%）、SkyWalk全日3,500泰铢。本程定版主推「半日上午场」：约7:30酒店接人、含素食自助午餐、约14:00回酒店，纯观察不骑不洗澡、Hands Off口径；它与SkyWalk全日的区别只在时长与步道段——全日含SkyWalk高架步道俯瞰象群段，半日没有步道段，胜在只占半天（2026-10-24定版口径，官网项目与价格2026-10-24实查）、2天1夜5,800泰铢，费用含酒店往返接送、餐食、向导与保险；以喂食和观察为主，没有幼象、以年长救援象为主不是缺点；认准官方渠道，警惕名字相似却仍拴链或提供骑乘的冒牌“庇护所”。小红书第50轮实测（2026-09-28，11帖转done）：亚洲首个伦理型大象庇护所，园内116头大象（盲象/残疾象/孤儿象/老年象），不强迫互动洗澡；官网预订（定金线上付、余款现场现金），门票包酒店接送；旺季提前订，半天约2500铢。SkyWalk 高架步道俯看象群是招牌视角。须披露：ENP 因进行中的法律调查被世界动物保护协会 2025-12 评审暂时移出「大象友好」名单，同指南称不影响象群福利与参观质量、TripAdvisor 仍标符合其动物福利政策。','必玩（清迈第一优先）：本程定版走半日上午场（฿2,500，见行程 12-16）；只走官网付订金锁位、12 月旺季提前 4–6 周；余额尽量带现金（刷卡＋3%），不同套餐活动内容不同、下单看清。'),A('Jungle Flight 丛林飞跃','清迈','清迈近郊雨林里的高空滑索乐园，招牌是 1,100 米滑索过山车；JF2 套餐 35 个平台、19 条滑索、最长一条 800 米，刺激量拉满的一个上午。','营地在 Doi Saket 的 Pa Miang、离古城约 1 小时车程。两档套餐：JF1（33 平台、无过山车、8–70 岁、全程约 4 小时）与 JF2（含 1,100 米滑索过山车、35 平台／19 滑索／5 天桥／13 空中步道／1 速降／1 螺旋梯、限 15–60 岁、全程约 6 小时）；JF2 代理价 ฿2,800／人（平台价约 US$85–88），含酒店接送、营地午餐、茶水与急救保险；每日 4 个接人档 8:00–8:30／9:30–10:00／11:00–11:30／12:30–13:00，一档约 14:00–15:00 送回；接送超出古城 1 公里可能加收 ฿500–1,500、订时确认。限制：体重上限 120 kg、身高至少 100 cm；孕妇及背颈、心脏、高血压、癫痫问题者不适合；官方口径用欧标（Petzl）双锁扣双钢缆系统。订法：官网或代理／平台，出发前 24 小时免费取消（多渠道一致口径）。运营商 TripAdvisor 4.7／5（804 条）。','值得玩（本程已定版排 12-17 早班）：订 JF2 的 8:00 一档，回城不耽误下午。安全记录必须知道：2024-08-01 园区内一棵大树在雨季连日大雨后倒下砸中吊桥，一名 44 岁中国游客身亡、其丈夫重伤（曼谷邮报 2024-08-03 报道），园区随后被勒令停业检查，保险口径死亡赔 ฿100 万／受伤 ฿50 万；另有一条 2024 年评价称终点刹车环节出过膝伤（TripAdvisor 单条评价、未独立核实）。12 月是旱季、与事发时情形不同，但务必全程听教练口令、终点段提前收腿减速，雨天或大风天直接改期。证据 hidden_files/tour-research/jungle-flight-2026-10-24.md。'),A('周日步行街','清迈','清迈规模最大的封路夜市，去的是逛吃买的气氛不是淘宝；纪念品同质化严重，和周六Wua Lai二选一。','地址 Rachadamnoen Road, Si Phum 50200，从塔佩门沿路至帕辛寺；仅周日17:00–22:00封街（摊位傍晚陆续出摊），免费开放、消费另计；古城内步行可达，古城外乘双条车或 Grab 到塔佩门；全程逾1公里穿舒适鞋，17:00左右到人少好逛，价格可砍价；与周六Wua Lai二选一，不连续两晚。','17:00入场避高峰；小红书3帖新标准核销（3推，2026-09-26落盘）：塔佩门至帕辛寺近2公里、仅周日17:00–23:00；沿街寺庙即美食广场（Wat Si Koet最推荐，场地大座位多烟火气足）；只收现金备好零钱；卫生间收费5–10铢；榴莲偏贵，红毛丹/山竹/龙宫果才真便宜；商品同质化严重、行前管好预期。'),
A('清迈大学夜市','清迈','10篇清迈路线帖8篇提到清迈大学一带，夜市是路线共识的必去晚间节目；学生消费区，价格友好，白天可顺带逛静心湖。','清迈大学正门与后门一带的夜市，17:00后才热闹，白天别跑空；学生消费区、小吃摊密集、价格友好。后门夜市有路线帖实吃推荐：打抛饭配龙眼冰（7-11对面那家）。白天可先进清迈大学逛静心湖、等落日，校门口还能租泰国校服拍照（路线帖记3小时约25元）；与长康路夜市二选一即可。','17:00后去。'),A('宁曼路','清迈','清迈年轻人的真实生活区：独立咖啡馆和设计小店，没古寺厚重但够松弛；寺庙看累了来呼吸一两小时。','Nimmanhaemin Road, Suthep，北起 Huay Kaew 路 Maya 路口向南、核心段 Soi 1–17；公共街道无开放时间，沿街店铺约10:00–22:00、One Nimman 11:00–22:00，免费逛、消费另计；古城乘红色双条车约30–40泰铢/人（跟司机说 Nimman）、或 tuk-tuk/Grab 以 Maya 为地标；傍晚散步加晚餐，One Nimman 庭院周一/周二16:00起有跳蚤市集。','白天或傍晚慢逛；小红书10帖严格重验（6推/2中/2不推荐，2026-09-21落盘）：One Nimman是颜值担当（红砖市集+钟楼，建议11:00后到；二楼单向街区从玛雅对面外侧电梯上楼最省力；White Market仅周五–周日15:00–22:00）；7号巷多帖公认最好看；MAYA顶楼天台可远观素贴山；MAYA对面Play Works文具店、5街Palit棉麻店值得逛；Roast8ry Coffee Lab冠军拉花店仅现金支付。预期管理：不是南京东路式商圈，车多尘大、物价比老城贵，逛的是咖啡香氛设计小店的松弛感。'),A('Baan Kang Wat','清迈','手作爱好者的天堂：约40家职人小店和陶艺工坊，工作日午后安安静静随手拍都好看；纯打卡心态可以直接舍。','地址 191 Soi 6 Raksa, Ban Ram Poeng Road, Suthep（素贴区）；周二至周日11:00–18:00、周一闭园，周末市集周六至周日8:00–13:00；免费入场；距市区约7公里，红色双条车或Grab/打车可达（Klook样本150–180泰铢）；约40家职人小店、多只收现金备零钱，想逛市集赶周日早上、工作日来更安静。','周二至周五去，可与乌蒙寺同线；小红书3帖新标准核销（3推，2026-09-24落盘）：本地艺术家Big带头打造的林间手作村（木屋工作室+手作店+咖啡店混在一起）；店铺大多10:00–17:00、周一休息，早上来最舒服（工作日人少、周末人多）；陶艺蓝染等DIY课程、藤蔓老屋与彩虹阶梯好拍；评论区公认椰子蛋糕好吃、咖啡店二楼可坐一下午。'),A('乌蒙寺','清迈','700年的隧道古寺，没有门票没有喧哗，至今仍是修行之地；和古城金碧辉煌的寺完全两种气质，安静派必去。','地址 135 Suthep, Chiang Mai 50200，素贴山脚、清迈大学南侧；每日4:00–20:00，免费入场、接受捐赠；tuk-tuk/双条车可达，可与清迈大学、素贴一带顺路串联；700年兰纳隧道寺，隧道低矮注意头部，宗教场所遮肩盖膝、保持安静，建议早上8–11点去，顺带湖边喂鱼。','保持安静，与Baan Kang Wat同线；小红书结论（2026-09-24落盘3/3）：要的是素贴山脚的"隧道里的寺庙"，导航搜"悟孟寺"，别导错到女子监狱旁的乌蒙寺；进入隧道20铢靠自觉付款；院内鸡多、晨昏蚊虫多；与Baan Kang Wat步行约15分钟可串。'),A('瓦洛洛市场','清迈','清迈人每天的菜篮子：泰北熟食伴手礼一次买齐的真实市场，不是为游客搭的布景；别把它当餐厅。','地址 Wichayanon Road, Chiang Mai 50300，滨河 Nawarat 桥北、Ping 河西侧；每日约4:00–19:00（周四约至17:00），免费开放、消费另计；古城乘 tuk-tuk/双条车或 Grab 前往；清迈人传统市场，买果干、干货与泰北伴手礼可砍价，早上到生鲜最全，入夜市场外道路变夜市、约20:00最热闹；生鲜气味较重，敏感者留意。','早上去（早7–9点人少凉快），顺访花市；小红书3帖新标准核销（3推，2026-09-22落盘）：伴手礼价格全城最低一档（果干可逐店试吃、试吃给一整包、店员会中文；门口山竹约25铢；老虎膏药10贴240铢、鼻通6个100铢）；韩贝贝避坑：95%商家18:00前闭店、别太晚去，买时问清有没有干燥剂（增重坑）并还价；不同声音：环境脏乱差（评论区）、商场可能更便宜；只收现金备零钱。'),
A('攀牙湾','普吉','普吉周边含金量最高的一日游：007岛、皮划艇钻潟湖、高脚屋村一次集齐；晕船、带老人或孕妇同行的先掂量健康限制和一天的强度。本程定版排 12-14 纯玩一日（运营商见「攀牙湾 · Amazing Canoeing 独木舟团」条目）：只订纯玩版，不捆漂流／骑象／动物表演。','普吉东北约30公里海域，一日游多为全天8–9小时、样本约08:00出发–16:30返回、基本含酒店接送（住偏远处可能加收）；常规停靠007岛、Koh Panyee水上高脚屋村午餐与海蚀洞，皮划艇钻喀斯特隐秘潟湖是大船进不去的亮点；价格样本：基础拼团约1,200泰铢起、含皮划艇午餐约US$55–110/人，国家公园费成人300泰铢、儿童100泰铢多为另付；大船较平稳、快艇覆盖多但赶而颠簸、长尾船慢而有味道；部分产品限制60岁以上、孕妇及特定疾病人群。Google Maps 4.7星，评价称石灰岩群岛壮观、拥挤感会被景色抵消。小红书第48轮实测（2026-09-28，3帖转done）：Melody小雨酱《攀牙湾出海一日游！真比皮皮岛好玩》（101赞）——星光日落号约570/人，12:00登船20:30返，酒店接送；皮划艇钻潟湖体验感超绝，做好防晒。注意该帖是中午登船的星光／日落变体、不是本程定版的白天团。本程定版（2026-10-23 用户定版 PDF＋2026-10-24 tour 研究第 6 项）：12-14 从 Dinso／芭东接人走白天纯玩线，专人划独木舟穿 Panak 海蚀洞与 Hong 岛潟湖、007 岛打卡、盘宜岛（Panyee）水上渔村午餐、Naka 岛游泳收尾，约 17:00 回酒店，晚间回 Dinso 休息。','已定版（12-14 主线）：按 Amazing Canoeing 白天纯玩团订，提前 3–7 天、报名前核对健康与年龄条款；不订捆绑漂流／骑象的拼盘版。'),A('皮皮岛','普吉','普吉周边最值得占一整天的岛：玛雅湾、双海湾观景台、浮潜看海龟一网打尽；旺季人挤人是真的。本程定版已排：12-12 包船走 Simba 日出团（见「Simba 皮皮岛日出团」条目），与 12-14 攀牙湾纯玩日各占一天、不冲突。小红书第48轮对比帖《攀牙湾出海一日游！真比皮皮岛好玩》（101赞）倾向攀牙湾（皮皮岛旺季人挤人）。','皮皮群岛由大皮皮岛（Phi Phi Don）与小皮皮岛（Phi Phi Leh）组成，一日游从普吉东岸码头乘快艇出发，以船团为主：快艇拼团样本约07:00出发、17:30返回（8.5–10小时，含酒店接送）；Klook样本¥264起/成人（含午餐、浮潜用具、国家公园门票，各团所含不同，下单逐项看行程单），豪华游艇约NT$2,068起、私人团约¥4,906（均为OTA样本）；常规点位玛雅湾、皮雷潟湖、维京洞穴、猴子海滩与观景台；玛雅湾只能观景拍照、不能下水，且玛雅湾与罗沙玛湾每年8/1–9/30关闭；0–3岁多为免费，多数船团不接待65岁以上、孕妇及心脑血管疾病者；带泳衣、防晒、毛巾、现金与个人药品，快艇颠簸、旺季拥挤；怕大团挤可看Simba皮皮岛日出团条目。','已定版（12-12 主线）：按 Simba 日出团口径订（约 05:00 酒店接人、约 15:00 回酒店，赶得上当晚 17:45 PRU）；本条目是目的地版，产品与订法见「Simba 皮皮岛日出团」条目。'),A('大佛','普吉','45米高白大理石大佛、南部最好的360度制高点，和查龙寺拼车1小时看完；单独跑一趟不值，顺路就行。2026-10-24 查证：2026-03-03 正式重开，现行开放约 9:00–18:00、末入场 17:30、免费；本程定版是下午包车第一站，日落留给神仙半岛；宗教场所着装必须遮肩遮膝；让司机送上山可能被额外收车辆磨损费；沿路铜钟可逐个敲响许愿、32个功德碗投硬币祈福；猴子出没在面对大佛最高点左侧卖香处旁的小路，不要投喂、对视，容易被抓伤；骑摩托上山路陡，注意安全。','地址 Soi Yot Sane 1, Karon, Muang, Phuket 83100，Nakkerd 山顶；现行开放约 9:00–18:00、末入场 17:30（2026-10-24 查证口径，取代旧帖 6:00–19:30 说法），免费开放、接受捐款；现由 Wat Kata（Wat Kittisangharam）管理，可游览范围缩小为围栏区内，部分旧建筑与花园仍待整。山上无公交，需 Grab／包车／tuk-tuk 上山，山路多弯坡陡、部分路段破损，小排量摩托吃力；徒步卡伦出发约 2.5 公里、卡塔约 8 公里。着装遮肩盖膝、忌沙滩装与短裙，穿得暴露可向现场免费借纱笼。2024 年 8 月山体滑坡（13 人遇难）后长期关闭，2026 年 1 月曾短暂重开 3 天又关，2026-03-03 起正式重开并持续开放至今；因有反复前科，出发前一天让酒店礼宾再确认当天开放；山上猴子较凶。与查龙寺相距约 8 公里，串成经典半日线。','值得玩（定版包车线第一站）：13:00 包车先到这里停约 1 小时，再接查龙寺与神仙半岛日落；末入场 17:30 别拖，行前让酒店确认开放，收好食物防猴。'),A('普吉老镇','普吉','普吉唯一的人文半天：锡矿潮、中葡骑楼、福建面，看懂老镇才算看懂普吉的另一面；纯冲海滩的人可以舍。小红书手搓路线实测：全程约1.8公里，半天逛完，夏季建议下午4点后再去；起点Museum Phuket经典黄色洋楼很出片，途中鑫發（平价米其林）牛肉汤被点名推荐——牛肉不柴、牛丸Q弹；走到尽头步行街夜市的大寺庙想进去参观要穿长裤；终点Phuket Camera可坐公交回机场，约1小时。小红书第48轮实测（2026-09-28，4帖转done）：Lard Yai周日16:00–22:00，Thalang路（搜Sunday Walking Market）；火山排骨/芒果糯米饭/泰式烤鱿鱼/椰子糕平价不踩雷，人均约50元，被称"泰兰德烟火气天花板"；天黑后灯光超美巨出片；部分摊位只能现金。','以 Thalang Road 为核心，Talat Yai, Mueang, Phuket 83000；街区全天开放、免费逛，具体项目另计，Lard Yai 周日步行街约16:00–22:00；老城紧凑以步行为主，住别处用 Grab 到达；清晨或傍晚凉快时逛中葡骑楼与街头壁画、Soi Romanee 拍照，周日17:00左右到夜市避高峰、摊位多只收现金，顺路试 Raya / Tu Kab Khao。','17:00左右到并带现金。'),A('查龙寺','普吉','普吉29座庙里最重要的一座：60米佛塔加龙婆禅平定锡矿暴动的传奇；不用单独留时间，跟大佛、老镇串成一条线。小红书实测：免费入场，开放7:00–17:00，地址70 Moo 6, Chaofa West Rd；普吉打车到处都好叫但“死贵”，串线包车更划算。','地址 70/6 Chao Fah Tawan Tok Road, Chalong, Phuket 83130；每日07:00–17:00（庭院可随时逛，建筑内部另有09:00–17:00口径，参观按内部时段规划），免费入场（供品香花金箔约20泰铢）；普吉镇西南约8公里、芭东东南约16–18公里，Grab/出租/宋条车可达，自驾有免费停车；着装遮肩盖膝、禁无袖与短裙短裤，进殿脱鞋；登60米三层舍利塔顶层可观全景并远眺大佛，与大佛相距约8公里，串成经典半日线。','与大佛/老镇同线。'),A('神仙半岛','普吉','普吉公认第一日落点，“上帝之角”名不虚传；想要仪式感就傍晚去一次，想清净就留在海滩上看，不必两头跑。小红书第76轮实测（2026-10-02，3篇达标转done）：泰国吃喝玩乐《普吉神仙半岛 德和欧儿同款橘子色日落🌅》（181赞）——查好当天Sunset时间（通常18:15–18:45）、务必17:00–17:30前到；租摩托车最推荐；观景台下有泥土碎石路可走到延伸进海里的最前端礁石；包包出走世界《吹爆普吉岛落日｜观赏指南》（55赞）：神仙半岛最经典、卡塔观景台俯瞰三湾、蓝调时刻（日落后10–25分钟）更出片；不插电的超人：Laem Sai Cup Cafe悬崖咖啡厅低消100泰铢很出片、步行20分钟边走边拍。','地址：普吉最南端、Rawai 以南约 2 公里，导航 Laem Phromthep；全天 24 小时开放、免费。日落约 18:00–18:30（随季节），至少提前 30 分钟到占位。交通：距芭东约 20 公里、卡塔约 10 公里，Grab／出租约 400–800 泰铢，也可宋条车到 Rawai 再转约 30–50 泰铢／人；日落后返程车难找，提前约好返程或与司机谈往返。坡陡路滑穿抓地好的运动鞋；太阳落山前后蚊子多、提前喷防蚊液；礁石岬角无沙滩、不可游泳，想游泳去附近 Nai Harn 海滩，登 Kanchanaphisek 灯塔露台可 360° 眺望，可搭 Rawai 与风车观景台。','提前到占位。'),A('卡塔诺伊海滩','普吉','老玩家私藏的安静海滩：沙细水清、人只有隔壁一半，躺一天发呆正好；要夜生活的别来，晚上这里很安静。','卡塔海滩以南约800米、死路尽头两岬角之间（Karon区）；全天开放、免费，无直达公交，只能打车/Bolt/Grab（卡伦出发约20–30分钟），或从卡塔翻山步行约1公里（先陡坡后台阶），停车位有限更建议打车；Google Maps 4.6星、3,002条评价，评价称沙滩干净、水浅易入水、比邻近海滩人少清净，适合游泳、放松与看日落；5–10月浪高可达2米、不谙水性慎下水，南端礁石区适合浮潜看热带鱼与珊瑚；自带防晒，入口小餐馆价格实惠。','按海况现场确认。'),A('Phuket Elephant Sanctuary','普吉','普吉唯一能闭眼选的大象庇护所：不骑不表演，只在空中步道上远远地看；在意动物福利才值得花半天，时间紧直接舍。小红书第76轮实测（2026-10-02，3篇达标转done）：interesDing《在这里它们终于变回了大象🐘》（353赞）——公益性质保护基地，大象多为从伐木业/骑行营救助的老龄残障带伤个体；每天仅接待200名访客，门票收入100%用于大象食物和医疗，预约参观提前规划；评论区高赞"拒绝动物表演""不打扰大象"。','地址 100/9 Moo 2, Paklok, Thalang 83110，普吉东北部雨林；Canopy Walkway 每日4场（9:30/10:00/14:00/14:30起、约1.5小时）成人1,900泰铢，Half Day 约3.5小时成人3,000泰铢起；官网提前预约（热门场次易售罄）、可选往返拼车，自行 Grab/Bolt 到主路办公室再转园区接驳；纯观察、无骑象无共浴、保持距离，别混淆 Elephant Jungle Sanctuary。','选择官方项目。'),A('Siam Niramit','普吉','百余名演员70分钟讲完泰国七百年，第一次来泰国值得看；但白天玩透了晚上容易犯困，犯困就直接舍。','地址 55/81 Moo 5, Chalermprakiet Rd., Rassada（普吉市区，Grab可达）；周三–周一开放、周二无场次，园区约17:30–22:30。流程：17:30入园先吃泰式街头自助（约17:30–20:00），逛百年泰村，19:45 Naga庭院前秀，20:00剧院开，20:30正秀约70–80分钟（150+演员、500套服装）。票价OTA样本：纯演出Silver 1,530/Gold 1,700/Platinum 1,870泰铢，含自助+接送组合最高Platinum 2,200泰铢，儿童按身高100–140cm计儿童价；套餐多含酒店往返接送。小红书第44轮实测（2026-09-28，4篇有效帖转done）：拉布布《普吉岛被严重低估的秀》（1037赞）——铂金位置+自助餐约230元，17:30可入园，先在餐厅吃饱再逛泰式村（剪纸/编小鱼体验/小船拍照好看）；叶儿绿称"普吉岛文旅天花板"；散场不好打车，建议预约接送。','提前到逛泰式村。'),A('芭东 Bangla 路','普吉','成年人夜生活街：霓虹酒吧夜店一条龙，不好这口直接跳过；路过时傍晚快速穿过30分钟足够，别专程夜游。小红书实测：整条街约400米，20:00后渐热闹、22:00–00:00氛围最顶；女生友好、独自前往的安全反馈正面；深夜回程打车用Grab。','地址 Soi Bangla, Patong, Kathu 83150，芭东海滩旁约400米；每日约18:00封路成步行街，酒吧18:00起营业、夜店至凌晨2–5点，22:00–00:00最热闹；逛街免费，消费样本：本地啤酒约100–200泰铢、鸡尾酒200–400、大夜店门票300–1,000泰铢；住芭东步行即达、住别处回程用Grab避不打表车；点单先看价目、用计算器确认金额再结账，人多处看好财物（背包背前面、钱包手机放贴身拉链内袋）；19:00–21:00相对家庭友好；拒绝一切毒品搭讪（泰国法律极严），紧急情况找旅游警察1155。','如住芭东可傍晚快速路过；想体验氛围的22点前后去，散场用Grab回程。'),
A('Boat Avenue 周五夜市 Fun Friday','普吉','乐古浪一带的周五限定夜市：只有周五晚才有市，平时只是个冷清的商业区；体量小、餐饮偏西式，定位是饭前散步不是正餐。本程定版排 12-11（周五）傍晚，逛完接 19:30 的 Jampa 晚餐——12-11 正是本程唯一对得上的周五晚。','定版傍晚段（2026-10-23 用户定版 PDF＋2026-10-24 定版落站，源见 cloudDayOverrides 12-11 时间线）：Boat Avenue 在乐古浪（Laguna）一带、离这两晚住的 Banyan Tree Phuket 不远，夜市英文名 Fun Friday。只有周五晚有市——帖级实证（美食发掘 round 384，2026-10-21）：作者非周五到访只见冷清商业区、评论确认「周五晚上才有夜市」，另有帖封面 BOAT AVE FRIDAY NIGHT MARKET 佐证；乐古浪长住帖亦称周五 Boat Avenue 夜市值得逛。街区免费逛、餐饮消费另计；体量小、餐饮偏西式，别吃撑、正餐在 Jampa。具体开市与收市钟点帖内未明确，从酒店前往的车程与接驳方式亦未明确，临行按现场与地图复核、不按某个钟点锁死行程。','已定版（12-11 傍晚主线）：只在周五晚去、饭前慢逛即可；到得晚或太累就整段放弃、直接去晚餐或回酒店，不为它硬撑，更不要非周五专程跑一趟。'),
A('NAKA Weekend Market 周末夜市','普吉','普吉三大夜市之一、号称泰南最大街头美食中心：只有周六和周日才开，周内去必然扑空。本程 12-12（周六）与 12-13（周日）两晚都对得上窗口，但行程日口径只作备选——两晚只选一晚，不必两晚都赶。','双帖互证帖级坐实（源见 cloudDayOverrides 12-12 时间线）：泰国国家旅游局官方号帖（2026-10-11）＋本地博主源头帖《普吉岛NAKA夜市重装开业啦》（牛仔酷在普吉岛，2026-05-02）——2026-05-02 重装开业、新建大型钢架屋篷、有顶棚不怕雨；在 Central Festival 旁、距普吉镇老城约 10 分钟车程；每周六、周日 16:00–22:00，源头帖作者多次回复确认仅周末营业、周内不开。小吃消费另计；只逛小吃摊——坐下点海鲜的大排档有调包避雷实帖，别进。从这两晚酒店前往的具体车程与摊位清单帖内未明确，临行按地图与现场复核。附带备查：Chillva Market 周一至周六 17:00–23:00、周日休息，Indy Night Market 周三至周五 16:00–22:00（同源帖口径）。','备选（行程日确定备选，非定版主线）：12-12 先保已订 PRU 17:45，只作 PRU 前后顺路备选；或 12-13 逛完 Lard Yai 周日步行街后作第二站——两晚只选一晚；周一至周五别专程跑。'),
A('乔治市世遗核心区','槟城','槟城两天里你花时间最多的地方：华人宗祠、印度庙、清真寺、殖民建筑压缩在几条步行街里；花半天走路半天吃东西，住就住这一带。','2008年7月7日列入UNESCO世遗，核心区109.38公顷、1,700多栋历史建筑，约2.5平方公里全程可步行（或骑行/三轮车）；街区全天开放、无门票，各景点与摊位时间不一。四条主街为 Pengkalan Weld、Lebuh Pantai、Jalan Masjid Kapitan Keling 与 Lorong Love，Armenian Street 壁画与姓氏桥都在圈内；机场到乔治市约30分钟车程，住这一带步行串联最省事。','正午进博物馆避热。'),A('Khoo Kongsi','槟城','乔治市只进一座宗祠就进它：全马最华丽的福建会馆，把南洋华人"同姓相帮"浓缩成一栋建筑；四十五分钟看完，塞进世遗步行线。','地址 18 Cannon Square（18 Lebuh Cannon），世遗区内步行可达，入口在 Cannon Street 朝 Acheen Street 清真寺方向的左侧（另有 Beach Street、Armenian Street 通道）。每日9:00–17:00开放（含周日与公共假期）；门票成人RM10、儿童RM1（个别平台样本写RM15，以现场为准）。早上或傍晚去避人潮、光线好；重点看屋顶剪瓷、宗祠正殿与旧式戏台，与壁画街串成一条线。','与世遗街区同线。'),A('姓氏桥','槟城','最有"活着的遗产"味道的一站：姓周桥是最大最开放的水上聚落，木屋住着人、神庙烧着香；一小时走完栈道看到海，只看周桥别闯私宅。','在 Pengkalan Weld（Weld Quay）, 10300 George Town，以姓周桥 Chew Jetty 为主：游客时段9:00–21:00，其他桥无固定时间、请白天或傍晚访。免费进入、欢迎捐赠。从 Armenian Street 步行10–15分钟，或搭 CAT 免费巴士、Rapid 101/104/201/307/401/204 到 Weld Quay，也可 Grab。这里仍是住人社区：走主栈道、低声、私宅禁入、拍照先问；木板不平穿防滑鞋，小摊多备现金，清晨或傍晚较凉爽，傍晚看日落与倒影最出片。','清晨去避人流。'),A('极乐寺','槟城','槟城必看No.1寺庙，马来西亚最大：中式大殿、泰式塔身、缅式穹顶三教合一；观音像和万佛宝塔两个制高点，体力留足一次拿下。','地址 1000-L, Tingkat Lembah Ria 1, Air Itam, 11500 Penang。每日8:00–17:00（游客样本另有8:30–17:30，以现场为准）；寺院大院免费，上行斜梯/电瓶车与宝塔另收费（游客样本：到顶往返套票RM16含斜梯与电瓶车、不含宝塔，分段斜梯RM3、电瓶车RM4、宝塔RM4，均样本价）。从乔治市 Grab 约30分钟，巴士班次较疏；与升旗山同在 Air Itam 排同一天。一早去避排队，先走最远的观音像与宝塔（各层时间不一），着装遮肩盖膝，预留约2小时。','先乘车到山顶再步行下山省体力。'),A('升旗山','槟城','和极乐寺绑定的主线，也是槟城看全景唯一正确的地方：山顶俯瞰全岛和马六甲海峡；两座山放进同一个半天顺路拿下。','缆车下站在 Jalan Stesen Bukit Bendera, Air Itam：Rapid 巴士 1/10/91/21 可达，或从乔治市打 Grab。缆车平日6:30–22:00、周末及公共假期至23:00，轨道长1,996米。往返票样本价成人RM30、儿童/学生RM15，Fast Lane 约RM80起（官网票价未直接核到，以现场为准）；周一至周四19:00后半价是看夜景的省钱玩法（样本口径）。务必早去避开普通通道长队；与极乐寺同在 Air Itam，排同一天。','出行前查官网运营状态。'),A('Fort Cornwallis','槟城','槟城故事的"第一页"：莱特1786年登陆地，但堡很小、半小时走完，一辈子没打过仗；殖民史爱好者顺路看一眼，时间紧让给壁画街和小吃。','地址 Jalan Tun Syed Sheh Barakbah, 10200 George Town，海滨世遗区边缘，乔治市中心步行可达，也可搭 Rapid Penang U102/U104/U105/U204 或 Hop-on Hop-off 第14站。每日8:00–20:00开放（周二19:00关门）；门票非 MyKad RM20、MyKad RM10，只刷卡不收现金。周五至周日10:00/12:00/14:00/16:00有导览；傍晚去避正午暴晒，出堡顺路吃附近傍晚小吃摊。','与海滨步行线结合。'),A('娘惹博物馆','槟城','乔治市最好的室内文化体验：1000多件娘惹文物讲峇峇娘惹美学；但老宅选一栋深度看就够了，和张弼士故居二选一，没执念可舍。','即 Pinang Peranakan Mansion（海记栈），地址 29 Church Street, 10200 George Town，世遗区步行可达（近壁画街与蓝屋），也可搭巴士103/204/502或 CAT Jetty 线，或 Grab。每日9:30–17:00开放（含公共假期）；成人RM25、6–12岁儿童RM12、6岁以下免费。每天11:30与15:30有免费英文/中文导览（约45分钟），踩导览点进收获更大；预留约2小时，与蓝屋、壁画街排半天，也可与 Auntie Gaik Lean 同区串联。','雨天或正午安排。'),A('卧佛寺与缅寺','槟城','一次看两种佛教传统的划算组合：33米大卧佛+马来西亚第一座缅寺；但不在主线上，宗教建筑爱好者顺路花一小时，时间紧可舍。','两寺在 Pulau Tikus 的 Lorong Burma 街对街：卧佛寺在 24 Lorong Burma，每日6:00–17:30（槟城旅游局口径）；缅寺在正对面，约9:00–17:00，是马来西亚唯一的缅甸寺庙、建于1803年。两寺均免费、随喜捐赠。从乔治市打 Grab 或搭巴士前往，离世遗核心区稍远。进殿须遮肩盖膝、脱鞋；傍晚可看卧佛寺亮灯的舍利塔。','短程组合。'),A('小印度','槟城','世遗区里味道最冲的一条街：香料、茉莉花、印度煎饼的香气混在一起，边走边吃最舒服；美食线排满了就顺路一逛，不必单独留时间。','香料、纺织与餐饮。','傍晚较舒适。'),A('和谐街','槟城','一条街四种信仰：教堂、观音亭、兴都庙、清真寺排排站，这就是"和谐街"名字的来历；就在世遗步行线边上，顺路走一遍就行。','即 Jalan Masjid Kapitan Keling（旧称 Pitt Street），街道全天开放、免费；从 Armenian Street、邱公司、小印度步行即到。一条街集齐甲必丹吉灵清真寺、观音亭（广福宫）、圣乔治教堂与斯里玛哈玛丽安曼印度庙。清真寺游客参观时段一说周六至周四13:00–17:00、周五15:00–17:00（旧来源），新来源称每日开放、避开礼拜时间，出发前以现场为准；入内着装端庄，现场提供长袍与头巾。清晨或傍晚逛避人潮。','与小印度同线。'),
A('双子塔','吉隆坡','吉隆坡唯一“不去会遗憾”的现代地标：从空中走廊到观景台，一次看懂这座城市从锡矿小镇长成国家门面的格局，是全程的高光时刻之一。','Kuala Lumpur City Centre, 50088，KLCC 商圈；每日9:00–21:00开放（马蜂窝口径记周一闭馆，两来源有出入，以官网/现场为准）；门票 OTA 样本成人约 RM80、马蜂窝记外地成人 RM98/老人儿童 RM50，以订票页为准；LRT/MRT 到 KLCC 站出站即 Suria KLCC；Skybridge 空中走廊+观景台分批限时、严格按预定时间入场，迟到可能被拒（有迟到约25分钟被拒入场样本），傍晚约18时场次可兼收日落与夜景；具体楼层不写未核实数字。','提前预订。'),A('黑风洞','吉隆坡','吉隆坡周边唯一"世界级"景点：42.7米金色战神像+272级彩虹阶梯，视觉冲击东南亚无出其右，值得专程跑一趟；它是印度教圣地，带点敬畏去。','Batu Caves, Gombak, 68100，市区以北约13公里；主洞 Temple Cave 每日约6:00–21:00、免费，Ramayana Cave 与 Cave Villa 各约 RM15（游客样本价）；KTM Komuter 从 KL Sentral 约30分钟直达 Batu Caves 终点站（单程约 RM2.60）、出站即入口，Grab 约 RM20/15–25分钟；272级阶梯入口查着装，肩膝须遮盖、不合规可现场买纱笼约 RM10–15；工作日9点前到最凉快人少，猴子会抢食物和塑料袋，食物与小件物品收好。','早晨去，遮肩盖膝。'),A('独立广场','吉隆坡','马来西亚的"出生地"：1957年国旗第一次在这里升起，2026年刚完成修复、是它最好看的时候；不用"玩"，过来站一会儿感受一下就行。小红书第83轮实测（2026-10-02，3篇达标转done）：Hélène《🇲🇾独立广场 大楼内部视角太好拍了》（02-21，369赞）——大楼内部免费进，"内部视角温柔又大气""天气很好阳光很强"，楼内有咖啡馆和展览，5号线Masjid Jamek站出来步行可达；Lavi《离开吉隆坡前一定要打卡的18个免费机位📷》（01-07，3519赞）收录独立广场机位。','Jalan Raja, 50050，老城核心；开放式公共广场全天开放（约00:00–23:59）、免费；LRT 到 Masjid Jamek 站沿 Jalan Raja 步行约5分钟、Bandaraya 站约9分钟；广场遮阴少、正午暴晒，早晨或下午来，黄昏前蓝调时刻拍照最好；95米旗杆是地标，与苏丹阿都沙末大厦、中央市场、茨厂街同线步行串联。','早晨或黄昏。'),A('吉隆坡塔','吉隆坡','跟双子塔看的是同一座城市：观景点更高更开阔，但“地标感”拼不过双子塔。登过双子塔这站可直接舍，除非你对玻璃地板或日落夜景有执念。','No. 2 Jalan Punchak, Off Jalan P Ramlee, 50250；每日9:00–22:00；外国成人票价样本有出入：Observation Deck 约 RM65–80、Sky Deck 约 RM114–140、联票约 RM147–180，以官网/订票页为准，Sky Box 另收费；Monorail Bukit Nanas 站步行3–5分钟、LRT Dang Wangi 站步行10–15分钟，从 KLCC 打车约5–10分钟；晴天清晨或日落时段最佳，雨天 Sky Deck 可能受限，线上预订可免排队。','晴天看景。'),A('茨厂街','吉隆坡','不是"景点"，是吉隆坡华人百年的生活现场：白天老字号吃福建面牛肉粉，晚上整街变夜市；吃饭+买手信+看市井一次搞定，效率最高的一站。小红书第83轮实测（2026-10-02，3篇达标转done）：yvette《不要去茨厂街！！》（05-29，634赞）避雷——评论区"千万别去"附和多条，本地人建议改去pasar seni附近chinatown的小众咖啡店和艺术展；Lavi《离开吉隆坡前一定要打卡的18个免费机位📷》（01-07，3519赞）点名BookXcess茨厂街迷宫书店是"很酷"的打卡点。想淘老字号吃食可来，纯冲"必打卡"名气的先降期待。','Jalan Petaling, City Centre, 50000；市场每日约10:00–22:00（部分店铺约9时至午夜，美食摊午后到晚间最旺）、街区免费、消费另计；MRT/LRT 到 Pasar Seni 站步行约3–5分钟；议价是常态，可按三至四成折扣目标谈，人多处看好财物；上午10–11时或18时后最合适，顺路拍 Kwai Chai Hong 鬼仔巷，福建面、牛肉粉与南香鸡饭等老店集中。','与REXKL、中央市场同线。'),A('武吉免登','吉隆坡','不用“游览”、用来“泡”的大本营：白天在Pavilion、Lot 10吹空调扫货，晚上去一街之隔的亚罗街吃夜宵。不专程打卡，住这附近就够了。小红书第83轮实测（2026-10-02，3篇达标转done）：POP学长《为了这❶❺张照片，我专门飞了一趟吉隆坡….》（03-27，2177赞）——"别再把吉隆坡当中转站了""值得停留3天时间好好逛逛"，D1路线含武吉免登、Saloma天桥、盛茂酒店33楼SkyBar、双子塔夜景；我是你的拉哥哥《🇲🇾1分钟带你找到吉隆坡A市神级机位》（2025-10-15，1808赞）——Lot 10对面十字路口（红黄撞色M标+黄色薯条斑马线）神级机位、Pavilion KL天桥夜景；谦德乐陈《吉隆坡最热闹的十字路口！武吉免登经典机位》（07-18）——武吉免登最热闹十字路口经典机位（机位线索已登记、图未到）。','Jalan Bukit Bintang, Bukit Bintang, 55100；街区全天开放、免费，商场与店铺多营业至深夜；一街之隔的 Jalan Alor 亚罗街美食摊每日约17:00–24:00、19–21时最热闹（单份约 RM10–25 样本，现金最方便、部分摊支持 QR 支付）；Monorail/MRT Bukit Bintang 站直达；Pavilion、Lot 10 等商场集中，白天逛街、晚上转亚罗街，同桌拼多家摊位分着吃。','步行连接商场。'),A('伊斯兰艺术博物馆','吉隆坡','东南亚同类博物馆里藏品最成体系的一家，对伊斯兰宗教艺术有兴趣值得留2小时。但在两天行程里排位靠后，先保中央市场和茨厂街。','Jalan Lembah Perdana, 50480；每日9:30–18:00（含公共假期，末入约17:30，开斋节与哈芝节闭馆；旧攻略的周一闭馆说法与每日开放口径冲突，以官网为准）；成人 RM20、学生/长者 RM10、6岁及以下免费（2024口径样本）；LRT Pasar Seni 站步行约10分钟、KTM Bank Negara 站亦可达，从 KL Sentral 打车约5分钟；至少留1.5小时，着装端庄，馆内可拍照但禁用闪光灯。','出行前官网确认。'),A('中央市场','吉隆坡','全城买手信性价比最高、最“体面”的地方：有空调、能议价、卖的是正经本地手工艺。和茨厂街锁死在同一晚，留1.5小时拎着伴手礼出来。小红书第83轮实测（2026-10-02，3篇达标转done）：Lavi《离开吉隆坡前一定要打卡的18个免费机位📷》（01-07，3519赞）——中央艺术坊3F是"很少看到人拍、比较小众的机位"；Hélène《🇲🇾独立广场 大楼内部视角太好拍了》（02-21，369赞）确认独立广场附近几百米即中央艺术市场，可同线步行串联。','Jalan Hang Kasturi, 50050，茨厂街旁；每日开放时间来源有出入（TripAdvisor 记10:00–22:00、另一来源记至20:00，以现场为准）、入场免费、购物另计；LRT Pasar Seni 站步行约5分钟、Masjid Jamek 站约10分钟，Go KL 紫线亦到 Pasar Seni 附近；馆内有冷气，本地手工艺品与手信集中，工艺摊可议价，平日来避周末人潮；注意洗手间收费。','与茨厂街同线。'),A('天后宫','吉隆坡','六层宝塔建筑上镜、山顶视野不错，但地处西南山上，打车单程约20分钟，两天行程里时间账不划算。不是妈祖/中式庙宇爱好者可舍，时间留给黑风洞。小红书第83轮实测（2026-10-02，3篇达标转done）：KL顽皮《🇲🇾吉隆坡天后宫求签攻略！摇出一支上上签》（2025-10-10，925赞）——求签攻略帖，作者亲测"问了三个不同方向的问题"解签有指引性，评论区追问解签uncle下午5点是否还在；ENENLIU《吉隆坡48h，我过得有点太舒服了》（04-23，560赞）——"平淡却莫名深刻""城市很松弛，老建筑和现代高楼混合并存"；大侠V5《吉隆坡嘴真严❗️藏着这美的古今同框机位不说》（2025-10-21，336赞）——天后宫中式古典建筑与远处默迪卡118（世界第二高楼）、国家电视塔古今同框，"晴天或者夜幕蓝调来拍"更佳（机位已登记、图未到）。','65, Persiaran Endah, Taman Persiaran Desa, 50460，位于山上；每日约9:00–18:00（含公共假期，少数博客记更长时段，以现场为准）、免费、捐赠随喜；无直达轨道，Grab/打车从市中心约20–30分钟，或先到 Bangsar 或 Mid Valley 一带再打车接驳；入殿遮肩盖膝、进祈祷厅脱鞋；清晨或傍晚光线最好、人较少。“东南亚最大之一”说法依据不足，不作定论。','不使用未证实之最。'),A('国家植物园','吉隆坡','两天行程里最可舍的一站：本地人晨跑野餐的免费绿肺，游客性价比太低——黑风洞和KLCC公园已经给了同样的“绿”。住得近可散步，别专程去。','Jalan Kebun Bunga, Tasik Perdana, 55100；每日约7:00–20:00（个别来源记至22:00，以现场为准）；园区本身免费，园内 KL Bird Park、蝴蝶园等独立景点另收费（飞禽公园成人约 RM63、9:00–18:00，与植物园是分开的景点别混淆）；KTM 到 Old Kuala Lumpur 站过街、经国家清真寺步行可达，公交 B101/B112/B115 在步行约5分钟处停靠，从 KL Sentral 步行路线沿高速较绕、打车更省事；与伊斯兰艺术博物馆、国家博物馆同区串联，晨间散步最舒适。','与博物馆同区，别误以为飞禽公园免费。'),
A('滨城市场','胡志明市','地标钟楼值得拍张照，但别当购物点——摊位全是游客价，品质还参差；想逛真正的本地市场去Tan Dinh或平西。','第一郡 Le Loi, Ben Thanh Ward：日场约6:00–18:00、夜市约18:00–22:00（各摊位时间不一）。摊主预期讲价，攻略建议从要价约一半起砍、绝不按首价成交；食品区拉客积极，这里也是扒手热点，带现金、看好随身物品。距 Saigon Square 约250米步行可达，可与中央邮局、统一宫串成第一郡核心圈；本站口径不变：只看钟楼建筑，真购物去 Tan Dinh 或平西。','快速外观后去Tan Dinh或Binh Tay。'),A('战争遗迹博物馆','胡志明市','2天历史线的必选项：内容沉重但真实，和统一宫、古芝地道连成完整越战叙事；只能看一个博物馆就选它。','28 Võ Văn Tần, District 3。每日7:30–17:30（含节假日），现场买票不用预约：成人40,000越南盾，6至15岁半价、6岁以下免费。第一郡打 Grab 约10–15分钟，从统一宫、红教堂一带步行约10分钟可达；建议8点开馆即到避开旅行团，留1.5–3小时；部分展厅图片较血腥，带小孩先规划参观路线，户外军机展区下午光线适合拍照。','可租语音导览。'),A('统一宫','胡志明市','历史主线核心、必去：1975年坦克撞开铁门那一刻在这里凝固，100个厅室几乎原样保留；留2小时细看。','135 Nam Kỳ Khởi Nghĩa, Bến Thành, District 1（另有 Nguyen Du 106 号门，售票8:00–16:00）。每日参观7:00–18:00（官网2025-08-01起口径）；官网价：通票（含展览）成人80,000越南盾、仅宫殿40,000、电瓶车25,000/人·次，儿童10,000–20,000。距红教堂、中央邮局步行约10分钟，第一郡内 Grab 方便；留1.5–2.5小时，地下战时指挥中心是精华别错过，有多语言免费讲解时蹭上，4月30日等纪念日人极多避开。','时间以现场为准。'),A('中央邮局','胡志明市','法殖民建筑里最值得进门的一座，而且还在营业：拱形大厅看一眼、顺手寄张明信片最地道；和红教堂并成一站。','2 Công xã Paris, Bến Nghé, District 1，红教堂正对面（过马路约2分钟，与书街同成一站）。1886–1891年建，常被误传为 Eiffel 设计。免费入场，纪念品与邮票另计；开放时间各来源略有出入（平日约7:30–19:00、周末约8:00–18:00为一说），以现场为准。公交04/36路到 1 Công xã Paris 站，Grab 也方便；早上8点左右去避开大型旅行团，在营业中的邮局里买明信片寄出（国际邮资另付），拍照别挡工作人员。','白天顺路寄明信片。'),A('红教堂','胡志明市','大修中，围挡包楼、进不去，只能看红色外墙和双塔轮廓；别为它单跑一趟，跟邮局和书街并成一站路过看一眼。','01 Công xã Paris, Bến Nghé, District 1，中央邮局正对面、过马路就到。免费；正常参观时段为每日8:00–11:00、15:00–16:00（中午闭馆别白跑），弥撒时间另行（平日5:30/17:30、周日多场）。公交36路到 Công xã Paris 站，第一郡中心步行可达。但2017年7月起大修、预计2027年底才完工，目前外观有脚手架，2026年12月按只能看红色外墙和双塔轮廓规划：早上绕教堂一周光线最好，与邮局、书街并成一站短停。','与邮局和书街合并15分钟短停。'),A('古芝地道','胡志明市','2天历史线的压轴：统一宫讲终点、博物馆讲代价，这里讲战争是怎么打的——钻一段地道比看书直观；认准Ben Duoc小团。','胡志明市古芝县，距市区西北约50公里。双入口：Ben Dinh 近而商业化、Ben Duoc 远而较安静（另有纪念庙），本站认准 Ben Duoc 小团。每日7:00–17:00，售票柜台约16:00关闭；门票 Ben Dinh 110,000、Ben Duoc 90,000越南盾/人（航司官网口径）。最省心报半日团：第一郡酒店约7:30接、约14:30返；自助公交需转车、单程约2.5小时，或 Grab 包车；含往返按半天5–7小时规划。隧道低矮狭窄，幽闭恐惧或腰背不适者只参观地面展区即可（钻洞可选）；穿运动鞋、带水、防晒和驱蚊，选上午团避正午暴晒。实弹射击60,000越南盾/发、最少600,000起（帖子样本，费用自理）。','认准Ben Duoc并备水。'),A('玉皇殿','胡志明市','本地人求子求姻缘香火最旺的道观，活生生的信仰场所；对道教建筑或本地信仰没兴趣可以直接跳过。','73 Mai Thi Luu, Đa Kao, District 1（奥巴马2016年到访过的道观）。每日约7:00–18:00，农历初一、十五延长至约5:00–19:00且香客极多、尽量避开；免费、无售票处，香油钱随喜。距统一宫以北约1.5公里，Grab约10分钟（约50,000越南盾样本），公交18/93/150路可达；着装遮肩盖膝、入内殿脱鞋、殿内禁止拍照，早上去人少清净。','保持安静。'),A('Bitexco 观景台','胡志明市','看全景的一个选项，但已不是全市最高：住第一郡顺路就上它，为登最高就去Landmark 81；两个不用都去。','Saigon Skydeck 在 Bitexco 金融塔（票务页地址 36 Hồ Tùng Mậu、楼体地址 2 Hai Trieu，位于三街交汇处），换票柜台在4层 Hải Triều 入口。每日9:30–21:30，售票柜台约20:45停止售票、最晚入场为闭馆前45分钟；门票约240,000越南盾/成人（OTA样本），4岁以下免费、4–12岁及65岁以上有优惠。第一郡核心，阮惠步行街一带步行或 Grab 可达，机场109路公交可到附近；选傍晚一次看日落加夜景、工作日人比周末少，台内禁饮食、禁宠物。为登最高仍去 Landmark 81，两个不用都去。','按所在片区和预算选择。'),A('堤岸唐人街','胡志明市','值得花半天：越南最大华人聚居区，天后宫香火、平西市场日常采购都比游客化的滨城实在；华人后裔会有奇妙的亲切感。','Chợ Lớn 华人区横跨第五、六郡，核心平西市场在 57A Tháp Mười, District 6（2,300多个摊位、以批发本地客为主），约7:00–18:00开放；街区与市场免费。距第一郡约5–6公里，Grab约15–20分钟（约30,000–50,000越南盾样本），公交1路从滨城一带约40分钟（票价5,000越南盾样本）；逛中式庙宇遮肩盖膝，人多处看好随身物品，留半天慢逛。','安排半日。'),A('阮惠步行街','胡志明市','傍晚限定景点：白天没什么可看，晚上才是完全体——咖啡公寓找个阳台位看夜景，1小时轻量散步就够。','Nguyễn Huệ, Ben Nghe, District 1：从市政厅前 Lê Thánh Tôn 到西贡河滨 Tôn Đức Thắng，长约670米、宽64米。全天开放、免费；周六与周日18:00–22:00机动车禁行、变纯步行街，是全周最佳时段。地铁1号线歌剧院站可达，第一郡内步行串联同起街与 Bitexco；傍晚到、找咖啡公寓阳台位看夜景，白天基本只是过路。','轻量散步。'),A('同起街','胡志明市','奢侈品商业街，不值得单为它安排时间；价值在串联——歌剧院、老牌酒店、法殖民街区都在这一线，顺路看一眼就行。','Đồng Khởi, District 1：从红教堂前巴黎公社广场经蓝山广场到西贡河边 Tôn Đức Thắng，长约630米。全天开放、免费（购物餐饮另计）。与阮惠步行街平行、步行即达，红教堂、中央邮局、歌剧院都在步行圈内，Grab 与公交也方便；街道单向通行、过马路注意车流；傍晚散步顺看歌剧院亮灯夜景最合适。','顺路即可。'),
A('跨海缆车','富国岛','富国岛体验天花板：7.9公里从安泰镇滑翔到香岛，脚下是安泰群岛的碧绿海水和渔船，票还含香岛水上乐园；不恐高就别犹豫，这一天稳赚。','出发站在 Sunset Town（安泰镇）的 Anh Duong 站、终点 Hon Thom 岛；全长7,899.9米、吉尼斯认证世界最长三线缆车，单程约15分钟；2026年新口径分段运行09:00–11:30、13:30–17:00、中午停运，出行前以 Sun World 官网/票面为准；官方往返价成人（>140cm）765,000盾、儿童（100–140cm）630,000盾，票含 Aquatopia 水上乐园与 Exotica；南岛 JW Marriott 距站约4.4公里、打车约10分钟样本，其余区域打车或 Grab；早上人少，别卡中午停运时段，天气与维护可能调整或关闭。','天气与维护可能关闭。'),A('星星海滩','富国岛','富国岛的明信片本体：奶粉细白沙加渐变海水，发呆拍照两小时不亏；但旺季人多时有垃圾、躺椅另收费，认准Paradiso一带。','位于富国岛东南海岸（Bãi Sao），距机场约16公里，与北部 Rach Vem 海星沙滩不是一处；无官方开放时间、全天免费进入；躺椅约50,000–70,000盾、遮阳伞与吊床各约30,000–50,000盾、淡水冲洗约20,000–40,000盾（Vinpearl 样本）；阳东镇打车、租摩托或跟团约40分钟–1小时；带泳衣、防晒与现金，椰树秋千出片，常与护国寺、富国岛监狱拼南线；旺季有垃圾问题，Paradiso 一带相对整洁。','06:00–09:00或16:00–18:00。'),A('Khem Beach','富国岛','比星星海滩更私密的水清好选择，沙子细人少；尴尬的是部分沙滩归酒店管理，非住客可能进不去——住南边沿线才值，专程跑先确认入口。','位于岛南端 An Thoi 区、JW Marriott Phu Quoc Emerald Bay 旁，距阳东镇约25公里、机场约18公里；无官方开放时间、白天前往为宜，免费开放，躺椅/遮阳伞另付小费、停车约1万–2万盾；阳东镇打车约30万–40万盾、机场约25万–35万盾；部分沙滩归度假村管理，非住客走度假村入口附近的公共通道进免费海滩区，水清沙细、椰林多，适合躺平半日。','提前确认公共入口或住沿线酒店。'),A('安泰群岛浮潜','富国岛','和跨海缆车并列的富国岛主线：出海一整天浮潜看珊瑚，水质在越南排第一梯队，体验上限极高；会晕船的慎重，其他人都该去。','出海集合点在安泰港（An Thoi pier），行程覆盖 Hon Thom 等安泰群岛海域；无固定开放时间、看所选团行程单，典型团程4–8小时；OTA样本拼团约29–39美元/人起、私团约56美元起；团多含酒店接送，阳东镇/Bai Truong/安泰免费接，其他区域按团加价（Klook样本最高50万盾/团）；Gam Ghi适合浮潜、May Rut偏拍照，优先选小团/私团，确认含浮潜装备、午餐与保险，恶劣天气会取消并退款。','备泳衣、防水袋与毛巾。'),A('VinWonders','富国岛','越南最大的主题乐园，水上乐园加机动游戏加水族馆，玩得开能耗一整天；机动游戏爱好者和带娃家庭可去，对乐园无感的人果断舍，海才是本体。','位于岛北 Bai Dai, Ganh Dau；每日9:00–19:30开放；官网价（2026）成人（≥140cm）950,000盾、儿童100–140cm与60岁以上长者710,000盾、1米以下儿童免费，与Safari联票成人1,500,000盾/儿童长者1,100,000盾；持票可免费搭VinBus电动班车（机场–大世界–VinWonders–Safari一线）；园区极大至少留一整天，必看龟形水族馆 Neptune Palace、Once秀（18:45–19:05）与音乐喷泉。','别下午才进园。'),A('Vinpearl Safari','富国岛','带娃家庭看过来：如果只能选一个人工景点，我投Safari一票——坐车近距离看长颈鹿、犀牛、斑马，半野生放养在东南亚不多见；没娃可直接舍。','位于岛北 Bãi Dài, Gành Dầu 一带，距阳东镇约30公里；开放8:30–16:00（一说9:00开门）；官网价（2026-01-07起）标准票成人850,000盾/儿童长者650,000盾，Night Safari成人700,000盾/儿童530,000盾，与VinWonders有联票；持票可免费搭VinBus电动班车接驳，或打车/包车前往；一早入园、预留3–4小时，重点坐Safari巴士加步行区，备防晒驱蚊、穿舒适鞋。','上午Safari、下午乐园。'),A('Dinh Cau 岩','富国岛','阳东镇的经典黄昏机位：免费的海边神庙，渔港渔船和落日同框，本地人也来祈福；别专程跑一趟，跟夜市拼成一晚才划算。','地址在阳东镇中心 Bach Dang 街、Khu phố 2 沿岸岩石上；免费入场，开放时间各来源说法不一（一说每日7:00–18:00、一说全天、一说至20:30），以现场为准；镇中心步行可达，看完日落步行约5分钟到 Dinh Cau 夜市；约29级台阶较滑注意脚下，进庙着装得体、殿内禁拍照、保持安静。','傍晚去。'),A('Ham Ninh 渔村','富国岛','别冲着原生态渔村来——堤岸边早已是纪念品市场加海鲜餐厅；当成海鲜半日游心态就对了，吃蟹看海，称重前一定先确认价格。','位于岛东岸 Hàm Ninh 公社、省道47号（Provincial Road 47），渔村全天开放、免费进入，各海鲜餐厅约9:00–22:00；距岛西 Novotel 一带约12公里、车程约20分钟，建议打车、Grab 或包车；餐厅人均约100,000–300,000越南盾为本地站点样本，选 Bé Ghẹ 等口碑店、点单前看清菜单与价格，部分小店只收现金；清晨看日出、傍晚看金色海面。','半日即可。'),A('富国岛夜市','富国岛','富国岛晚上的烟火气担当：边走边吃小吃、逛纪念品，一两小时气氛拉满；但海鲜大排档先问价再下单，真想吃海鲜大餐换别处。','主指 Dinh Cau 夜市，在阳东镇中心 Vo Thi Sau 街一带（另有 6 Bạch Đằng 为主入口说法）；每日约17:00–23:30，多数摊位18:00–24:00、20:00后最热闹，19:00–21:00为推荐时段；免门票、按消费付费，甜品约25,000–50,000越南盾样本、海鲜现秤按品项浮动；镇中心步行可达，深夜返程用叫车软件勿路边拦车；先逛一圈比价，海鲜先问清单位与做法是否加价，看好背包。','别把海鲜大餐押在夜市。'),A('护国寺','富国岛','富国岛最值得看的寺庙，而且免费：山上临海的仿李陈朝建筑，爬上龙阶回头就是山海全景；拼进南岛线轻松顺路看。','位于富国岛东南部 Suối Lớn，距阳东镇约20公里、距机场约10公里；每日6:00–18:00开放、免费入场；无公交直达，打车或租摩托走山路前往，常与星星海滩、富国岛监狱、跨海缆车拼成南线一日游；进殿遮肩盖膝、脱鞋、保持安静，清晨或傍晚去光线好，带帽子做好防晒。','与南岛线路同线。'),A('富国岛监狱','富国岛','富国岛唯一有分量的历史遗迹，但内容沉重：复原展陈直白刺眼，看完心情不会轻松；真对历史感兴趣再去，主打度假放松的跳过毫无遗憾。','地址 350 Nguyen Van Cu Street, An Thoi，岛南安泰一带，距阳东镇约30公里、打车约40–45分钟；开放时间各来源不一（一说7:30–11:00、13:30–17:00午休闭馆，一说7:00–17:00），以现场为准；多源称免费入场，一来源称语音导览约50,000越南盾；预留1.5–2小时，展陈直白沉重、儿童及敏感者慎入，着装得体；多个 OTA 行程页曾标注因维护暂停开放，出发前务必再确认。','按兴趣停留。'),A('鱼露工厂与胡椒园','富国岛','这不是个正式项目：富国岛的鱼露和胡椒值得你知道，但具体哪家可参观、收不收费没核实；南岛北岛线路过就顺路停三四十分钟看看，专程跑一趟没必要。','鱼露厂可看三家：Khai Hoan（Hung Vuong街，阳东镇）、Hung Thanh（Ngo Quyen街，阳东镇，除周日外8:00–17:00）、Phung Hung（An Thoi镇，9:00–21:00）；参观免费，鱼露约4.5–8.7美元/瓶，现场可品尝比对、从木桶取样，气味浓烈、敏感者备口罩；胡椒园各团去的园子不同、无统一地址与时间（样本 Bungalow Pepper Farm 在岛北 Cửa Cạn），多含在南线一日团里，11月–次年2月为胡椒采收季。','不单独成正式项目。'),
A('滨海湾花园','新加坡','新加坡必看第一：101公顷填海造出的未来花园，超级树加双温室把热带和未来感同时拉满；行程紧也要留足半天，温室全室内、阵雨来了正好躲进去。','地址 18 Marina Gardens Drive 018953；MRT Bayfront（CE1/DT16）出站步行即达。双温室（花穹＋云雾林）每日 9:00–21:00（末入场 20:30），双温室联票约 S$41/成人（Expedia OTA 样本），户外花园免费。灯光秀户外免费，大雨或雷暴可能取消；双温室为室内雨备。Garden Rhapsody灯光秀每晚19:45/20:45两场（每场约15分钟，免费无需预约；2026-03实测）。小红书机位攻略：Bayfront地铁站B出口，跟着"Bayfront Avenue"指示牌左走，以白色灯球为路标，到超级树前排草坪——灯光秀最佳位（人多早点到场占位）。温室票建议官网提前买（现场买也行），Klook约八折可再叠银行活动；公园本身24小时免费开放。云雾林和花穹都是室内冷气不闷热；傍晚去拍照效果稍差，OCBC空中步道傍晚逆光。','出发前查活动日历；春节期间最热闹有新年集市。'),A('环球影城','新加坡','带娃家庭直接舍掉不心疼：小娃一大半项目身高不够玩不了，门票不便宜，雨季户外项目说停就停；等娃五六岁敢坐过山车再来。','地址 8 Sentosa Gateway 098269（Resorts World Sentosa）；OTA非高峰成人票样本 S$78；多数项目室内或有遮阴。部分项目户外，雨天可能暂停。小红书实测（singapore-xhs §22 10帖：7推荐/1中立/2不推荐，2026-09-24新标准核销→done）：园区营业10:00–20:00（2026-07实测）；五大必玩——木乃伊复仇记（全园最恐怖）、变形金刚3D对决；避峰玩法：17:00入园（没怎么晒太阳、没怎么排队，"爽玩各种项目"，2026-06实测）；存包70分钟限制，部分存包收费6新起（2026-07实测）；地铁到Harbourfront站，首次上岛4新/人、回程不收，出发前在小红书找当天免费登岛二维码可省4新（2026-03实测）；门票约410元/人（2026-07实测，三家庭六口人吐槽"这次新加坡之行最不值"）；非高峰不买优速通也行（最长排队30分钟、多数15分钟内，评论实测）；太空堡垒/寻宝奇兵/未来水世界2026-05未开放，去前先查官网；劝退派称"感觉不如北京环球影城太多了"。','放在预报较好日；坚持要去就17:00后入园避峰。'),A('Singapore Oceanarium','新加坡','带娃闭眼入：全室内不怕阵雨，22个展区逛两小时，娃看水母鲨鱼企鹅眼睛根本挪不开——是雨季新加坡最省心的亲子选择。','地址 8 Sentosa Gateway, Sentosa Island 098269（圣淘沙名胜世界内，2025-07-24 扩建更名开业）；官网时间：周一至周五 10:00–19:00、周六周日与公共假期 09:00–21:00（特定日期可能提前闭馆，行前查官网），官网成人票 S$49 起。交通：地铁到 HarbourFront 站，转怡丰城 3 楼 Sentosa Express 捷运（S$4）上岛。面积扩至约3倍，带娃建议1.5–2.5小时（OTA样本建议约3小时逛完）、高峰可能分时入场。小红书实测（singapore-xhs §20，4篇：3推荐/1中立/0不推荐）："保姆级一日路线+避坑"、"36米长的巨型观景窗"、"亚洲最大海洋馆"；Klook购票用26SG800码打八折；避雷：票价贵、周末拥挤。中文站：TripAdvisor 4.3/5（6,979条）、Google Maps 4.6（33,609条）、携程4.6（10,775条）。','提前买票，雨天强选。'),A('夜间动物园','新加坡','带娃家庭舍得干脆：18点才开园，最值得看的场次正撞上小娃的哄睡时间，电车排队半小时起还要求全程安静；等娃上小学能熬夜再来。','地址 80 Mandai Lake Rd, Singapore 729826；每日 19:15–24:00（23:15 停止入场），官网非居民票成人 S$58、儿童 S$41；交通：地铁南北线 Khatib 站（NS14）转 171 路公交直达园区，晚上另有接驳回地铁站。热门 19:00 场可能售罄，入场与游园车排队长。小红书实测（2026-02，658赞）：Klook买完票还必须另行预约具体入场时段；想看的表演要提前扫码预约（只在演出开始前2小时开放预约）。入场选19:00/19:15场最值得——选太晚动物都累了、睡了；Creatures of the Night 表演约25分钟（19:30/20:30/21:30 场次口径，行前以官网为准），开园先坐游园电车再看表演；带驱蚊水、穿舒适鞋。小火车：自带3.5mm耳机调到频道2=中文（加钱选多语言小火车基本不用排队）。','提前订票早到，电车右侧视野较好，禁闪光灯。'),A('新加坡动物园与Bird Paradise','新加坡','也建议舍：两园都在万礼，离市区单程40分钟以上，半天耗在路上，动物园还多户外怕雨；看动物需求全新的Oceanarium室内馆完胜。','地址 80 Mandai Lake Rd 729826（Mandai Wildlife Reserve，两园同区）；动物园每日08:30–18:00；官网非居民票：动物园成人S$49／儿童S$34，Bird Paradise S$39起；平日或清晨开园时到，动物最活跃、人也少。动物园多户外；Bird Paradise 09:00–18:00，部分有顶。小红书实测（2026-03/07两帖）：日间动物园开放式、动物状态放松，小火车免费坐，表演淡季无需预约、直接看；热到爆（有人中暑吃保济丸才缓过来），防晒+水备足。交通：地铁到Khatib站，出A站台经7-11超市旁M2公交站，刷卡2.5新、约20分钟到；18:00关门，建议17:30前出门坐M2返（否则返程站回地铁站）。飞禽公园：进门第一个岔路往左是飞禽保护区；下午两三点是放饭时间（小鸟停路边喂食器上不怕人）；下午5点"展翅高飞"表演强烈推荐（鹦鹉会唱生日歌）；企鹅馆在保护区绕一圈下来。省钱：Klook动物园通票约八折再叠银行满减，比单买划算。','晴天同日安排，雨天改Oceanarium。'),A('鱼尾狮公园','新加坡','到新加坡不拍这张等于没来：8.6米鱼尾狮喷水是国家象征，免费、半小时搞定，和滨海湾花园、金沙串成一条线，顺路程度满分。','地址 1 Fullerton Rd, Singapore 049213，公园全天24小时开放、免费，鱼尾狮灯光亮到深夜；最近地铁 Raffles Place 站 H 口步行约5分钟（与新加坡河游船鱼尾狮登船点同一出口，顺路串联）。推荐时段：早上7:00–9:00人少光线柔和、傍晚18:30–20:00看日落与夜景，停留约30分钟拍照足够。对岸金沙 Spectra 水幕灯光秀：周日–周四20:00/21:00、周五–周六加22:00，每场约15分钟，免费无需预约，出发前以官网为准（2026年5月实测记录）；大雨雷暴可能取消。','下午4:30左右到，光线好人少（小红书实测建议）；地铁坐到莱佛士坊、H口出沿新加坡河散步过去。雨天改金沙商场或ArtScience。'),A('Jewel 星耀樟宜','新加坡','转场前日完美收官：就在机场边上，全室内，40米雨漩涡免费看，推车随便推；逛完买伴手礼、吃顿饭，回酒店早休息（明晨赶早班机飞普吉），最不费力的一个景点。','地址 78 Airport Boulevard 819666，综合体全天开放（约 00:00–23:59），Jewel 本身免费入场；Canopy Park 等付费景点约 10:00–21:00、票价 S$4.80 起（OTA 样本）；MRT 东西线到 Changi Airport 站（CG2），经 T2／T3 二楼连桥可达。小红书实测（singapore-xhs §25 10帖：9推荐/1中立/0不推荐，2026-09-28图片逐张审查补翻7篇高流量证据完整→done）：致命踩坑——瀑布根本不在航站楼！星耀樟宜是独立综合体（和T1连通、属机场公共陆地区域，不属T1/T2/T3航站楼），准确位置是Jewel商场1楼森林谷，落地入境第一件事直奔；瀑布10:00才有水，红眼航班早到会碰不上；最佳机位：1楼仰拍、4楼天桥俯拍（轻轨穿瀑布）。灯光秀平日约20:00/21:00，周末假日前夕可能加22:00，均以当日官网为准。','全室内，适合抵离日。'),A('ArtScience Museum','新加坡','不用专门排，但它是滨海湾片区的雨天保险：全室内，teamLab光影对小娃是降维打击；出发前查一下特展，有乐高恐龙类主题可直接转正。小红书实测（2026-09-28第16轮3篇转done）：新加坡旅游局官方帖《谁懂?来这里眼睛根本看不过来》(2025-07-02,180赞）；狮城探险家《救命!新加坡艺术科学博物馆也太好逛了!》(2025-06-25,84赞，正文含运动森林/太空长廊出片点提及）；KKEE《亲子游-艺术科学馆 最新避坑指南》(2026-06-26,18张图逐张核验）正文"不买票在门口拍照也很出片"。结论：运动森林/太空长廊是必出片点；门口不买票拍照也很出片，时间紧可只打卡外观。','地址 6 Bayfront Avenue, 018974（金沙旁）；周日至周四10:00–19:00（末入场18:00）、周五至周六10:00–21:00（末入场20:15）；单展览OTA样本约$17/成人，各展览分开售票、票价随展览轮换（官方价目未核到），下单前核对包含哪些展览；全员需票，建议提前预订。','雨天强选。'),A('牛车水','新加坡','三个族群区三选一它胜出：赢在室内加室外组合，免费的佛牙寺凉快能坐，逛完宝塔街吃碗叻沙买伴手礼，转场前日（12月10日）上午节奏刚刚好。','地址 Pagoda St 059203 一带街区，免费开放、具体项目另计；MRT Chinatown 站（NE4/DT19）A 口直达宝塔街（街市核心）；街区店铺摊档多约 10:00–22:00，佛牙寺一般免费入内（欢迎捐赠）；可顺路试 Lim Chee Guan 林志源肉干（有现烤试吃）。小红书实测（singapore-xhs §27 + 2026-10-05补采，琬君表姐2070赞半日逛吃攻略）："来新加坡没逛牛车水等于白来"；路线：地铁A口→宝塔街（伴手礼）→原貌馆→街头壁画→马里安曼兴都庙→牛车水大厦开吃（安珍薄饼$2.2、了凡油鸡饭、佳记娘惹粽）；晚上看夜景也不错。避雷帖："吐槽牛车水：7080年代落后感"。中文站：Trip.com 4.7分（2,188条）、马蜂窝1951条点评；马蜂窝原话：岛山十七号"‘Z’字形曲折悬挂…红灯笼…"、鱼老蓓"麦士威熟食中心…史密斯街…"。','雨天也可。'),A('小印度','新加坡','建议舍：族群区三选一，名额已给了牛车水；实龙岗路人多香料味重，小娃没共鸣、推车也难走；真感兴趣等二刷配上屠妖节灯饰才够味。','地址 Serangoon Rd 218021 一带街区，免费开放、具体项目另计；MRT Little India 站（NE7/DT12）最方便，Rochor（DT13）／Farrer Park（NE8）也可达；店铺餐馆多约 10:00 起营业，Mustafa Centre 24 小时营业；Tekka Centre 可吃 teh tarik（约 S$1.5）与印度煎饼 roti prata（约 S$3）。进兴都庙脱鞋；Mustafa Centre可作雨备。小红书实测（§27 momo🥔《新加坡小印度有感》推荐；2026-10-05补采 Starry秋秋✨232赞半日逛吃攻略）：Mustafa Centre慕斯塔法中心、Indian Heritage Centre印度文化遗产中心、Campbell Lane坎贝尔巷、Little India Arcade小印度拱廊；Mona 261赞帖：兴都庙拱廊桥狂出片。中文站：Trip.com 4.6分（51,441条）、马蜂窝1793条点评。','咖喱怕辣要提前说。'),A('Kampong Glam','新加坡','同样让位给牛车水：苏丹清真寺和哈芝巷是看点，但带小娃逛小店看壁画耐心撑不过一小时；留到娃能自己逛巷子拍照时再来。','街区无固定地址，核心在苏丹清真寺与Arab Street一带，免费逛、具体项目另计；最近地铁Bugis站（EW12/DT14），步行约10分钟到苏丹清真寺与街区中心；最佳时段是傍晚到晚上，Bussorah Street与哈芝巷的咖啡馆餐厅氛围最好；进清真寺需遮肩盖膝、脱鞋，入口可借长袍，周五12:00–14:00祷告时段不要入内参观。小红书人像机位（2026-09-27逐图审查转done）：苏丹回教堂拱门、Muscat Street、Bussorah Street、Drunken Balloon、Vintagewknd蓝店（RachelGUO🍒18张黄裙写真帖逐图核验；二刷拍人像直接用）。','雨天改Bugis室内。'),A('乌节路','新加坡','诚实说大概率要舍：看头在圣诞季灯饰，但灯饰是晚上的事，娃早睡的家庭根本看不到；白天它就是条购物街，别为它改行程。','地址为乌节路全长约2.2公里的购物街区（无单一门牌）；沿街商场每日约10:00–22:00，街区免费逛、消费另计；MRT Orchard站（NS22）／Somerset站（NS23）／Dhoby Ghaut站（NE6/NS24/CC1）均可达，商场之间有空调地下通道连通。小红书实测（singapore-xhs §25 8帖圣诞灯饰：7推荐/1中立，2026-09-28图片逐张审查补翻→done）：新加坡11月就开始过圣诞（往年Christmas on a Great Street约11月初–1月1日，2024年54天），12/06–12/10行程正踩圣诞季。2025实测3小时路线：Orchard Boulevard MRT→东陵坊赏雪→沿街装置→义安城广场赏雪→313圣诞装置→Dhoby Ghaut；或从ION Orchard出发打卡5大官方装置、终点在义安城看梦幻飘雪（Snow show固定表演）。避雷：2025年有帖认为灯光不如往年亮眼、平安夜倒计时人山人海；2026具体亮灯日期尚未公布，出发前查主办方官网。','出发前查主办方官网。'),A('圣淘沙海滩','新加坡','亲子游下半场：上午海洋馆、中午回酒店午睡，下午睡醒来玩沙玩水体力正好；带小娃首选巴拉望或西乐索，雨季玩之前先看天。','地址 Sentosa Island 099008，含 Siloso／Palawan／Tanjong 三片海滩；海滩全天至晚间开放、免费进入，日落观赏时段约17:30–19:00；Palawan 有吊桥通往亚洲大陆最南端小岛、Siloso 水上项目多、Tanjong 最清静。夜滑仅周五、周六；12月雨季需准备室内备选。小红书实测（singapore-xhs §28 10帖：9推荐/1不推荐 + 2026-09-27 老窗口轮次新增2篇达标转done）：上岛3种方式——捷运小火车（地铁 HarbourFront 站→怡丰城3楼 Sentosa Express，4新币/人往返）、缆车（约90元，17:00–19:00看夕阳最值）、步行上岛（怡丰城1楼圣淘沙步行道、约500米免费）；三大海滩间有免费穿梭巴士；一天玩不完（"一个环球影城就大半天"）。天际线斜坡滑车 Luge：官网可提前5–7天买票、E-ticket 直接进（也有住客实测现场买不需预约，旺季建议提前）；HarbourFront→怡丰城3层捷运小火车到 Beach Station；建议至少买4圈（约33新币）玩遍4条线，麒麟线最新最刺激；上午10点开门场最便宜不热人少；带娃有单独票种（不到110cm 和大人同车）；18:30–19:00场可看落日，Tanjong 海滩是"绝美日落"观赏点。避雷：岛上多处只收卡不收现金（no cash）。','放在预报较好时段。'),A('新加坡河游船','新加坡','三代最稳的黄昏项：40 分钟零步行，一程看完日落＋华灯＋约 20:00 近鱼尾狮灯光秀；已排在 12-07 黄昏班，娃状态差可整项跳过不亏。','克拉码头（Clarke Quay）上船、绕一圈回到同一地点；成人约28新币、儿童18新币（2025年7月实测，可刷卡；晚班价格另议）；19:30左右可看昼夜转换并可能从水上看灯光秀，大雨影响体验。另一运营商WaterB在Fort Canning／鱼尾狮公园／Bayfront North也有登船点，班次样本每日14:00–21:00、约每30分钟一班、成人S$29（OTA样本）；鱼尾狮公园登船点最近地铁Raffles Place站H口、步行约5分钟。两家班次与价格出行前以官网为准。小红书实测：上船坐右侧靠窗视野最好、无中文语音讲解、售票窗口有中文服务人员、儿童报年龄有优惠；末班时间各帖冲突（17:10／17:30 与 22:00／23:00 两说）未核实、以官网为准。','值得玩（看娃状态）：约 18:00 黄昏班避 19:00 排队峰，天气合适再去。'),A('Simba 皮皮岛日出团','普吉','精品小团出海：快艇硬上限 18 名成人、日出先到玛雅湾；官网汇总跨 TripAdvisor/Google/GetYourGuide 共 5,814 条验证评价、自家页 4.9/5（1,102 条）','Simba Sea Trips 的招牌日出团：约 05:00 酒店接人、06:00 Boat Lagoon 出发，07:15 抢在大团前到玛雅湾（12 月开放、只能观景拍照不能下水），全程 7 站含 Pileh Lagoon 浮潜，约 13:30 回码头午餐、约 15:00 回酒店。官网价 5,310 泰铢/人全包（国家公园费、接送、早餐＋午餐、税费），出发前 24 小时免费取消。小红书无 Simba 专帖，但一致骂皮皮岛大团（85% 时间在船上、玛雅湾只停 35 分钟）——小团日出正是解法。（2026-10-24 tour 研究＋小红书复核，证据 hidden_files/tour-research/phuket-tours-2026-10-24.md）','必玩（普吉出海首选）：提前 2–4 周官网订；订满用 V. Marine 日出团（3,900 泰铢）替补。'),A('斯米兰群岛','普吉','浮潜水质天花板：开放季 10 月 15 日至次年 5 月 15 日、12 月能见度最佳（可达 30 米），但船大人挤、体验两极。本程定版未选：12-12 已排皮皮岛、12-14 已排攀牙湾，出海日已满，不再加第三天','本地运营商（如 SeaStar）一日游：8 号岛帆船石观景→9 号岛浮潜→4 号岛午餐→5/6 号岛浮潜，全程 11–13 小时、约 18:30 后才回酒店；US$95–132/人，国家公园费成人 400 泰铢多为码头另付、下单前确认；每日限流约 3,500 人／日、不可过夜，须带护照信息（预订要护照号、备复印件或照片查验）；出发点是攀牙府 Thap Lamu 码头：约 04:30–05:30 普吉酒店接人、车程 1–1.5 小时再快艇 80–90 分钟到岛，船上限约 45 人；儿童公园费 200 泰铢；孕期禁参加、60 岁以上部分产品不可参加，下单前看清。小红书口径：目的地被夸为「普吉海水的天花板」，但中文大团（淘宝懒猫彩虹号）被避雷帖点名（等候区破、强制消费、导游索小费）——只选本地运营商、优先双体船更稳。面级线索称 9 号岛圣诞角一带遇海龟概率较高（未定版）；往返车船 6–7 小时、晕船药必备（小红书作者实证成年人坐船都难受、不建议带小朋友）。（2026-10-24 tour 研究＋小红书复核）','备选（定版未选）：海水是天花板，但全程 11–13 小时、往返车船 6–7 小时强度最大；本程定版出海日已满（12-12 皮皮岛＋12-14 攀牙湾），不再加。真要拿它替换皮皮岛日，才提前 2–3 周订本地团，当天晚上别再排别的。'),A('皇帝岛＋珊瑚岛一日游','普吉','轻量出海备选：船程短、全程约 5–7 小时就能玩完，皇帝岛浮潜水质中上；本程定版未选（定版砍掉清单含皇帝岛）：12-12 皮皮岛、12-14 攀牙湾已占满出海日；只有放弃某天出海又想轻松出海时才启用。','普吉近海轻量跳岛线：珊瑚岛（Koh Hae）船程约 15–20 分钟、皇帝岛（Racha Island）约 30 分钟即达，全程约 5–7 小时、约 16:30–17:00 回酒店。Klook 主力产品 4.5 分／1,039 条、US$33 起（2026-10-24 tour 研究）。精华是皇帝岛浮潜——小红书评论认为皇帝岛海水比玛雅湾更好；珊瑚岛浮潜一般、偏沙滩与水上项目（香蕉船、拖曳伞多另付费）。提前 3–7 天订即可。注意别排到需要赶晚餐的日子（如 12-12 晚 17:45 已订 PRU），当轻松日或半日项用。','备选（定版未选）：船程短、全程约 5–7 小时的轻量线；本程定版不排，启用时提前 3–7 天订即可，别排到需要赶晚餐的日子（如 12-12 晚 17:45 已订 PRU）。'),A('攀牙湾 · Amazing Canoeing 独木舟团','普吉','攀牙湾最强玩法：专人划舟钻进 Panak 海蚀洞、穿洞进 Hong 岛潟湖，不用自己划、湾内有遮蔽相对不看海况，是普吉最稳的海上日之一。','Amazing Canoeing 的攀牙湾白天独木舟团：快艇出湾后换独木舟，由专人划进 Panak 岛海蚀洞与 Hong 岛洞穴潟湖（hong 即洞穴潟湖），石灰岩内湖是攀牙湾的唯一性所在；邦岛（007 岛）本岛只是打卡、人挤，别抱高预期。Viator 4.9 分／1,501 条、快艇团 ฿2,900 起（2026-10-24 tour 研究）。全天行程：约 08:00–09:00 从 Dinso／芭东一带接人（常规接送区内）、约 17:00 回酒店；行程单顺序为 Panak 海蚀洞→Hong 岛潟湖→007 岛→盘宜岛水上渔村午餐→Naka 岛游泳收尾。定版红线：只订纯玩版、逐项核对行程单，不捆绑漂流／骑象／动物表演的拼盘产品。费用口径冲突：官网称全包、Viator 写国家公园费 ฿300／成人另付——以确认单为准。提前 3–7 天订、24 小时前免费取消（Viator 口径）。','已定版（12-14 主线运营商）：这是可直接下单的白天纯玩团、与目的地条目「攀牙湾」是同一天的产品版；提前 3–7 天订，下单逐项核对纯玩行程单与公园费口径。'),A('John Gray 星光团 Hong by Starlight','普吉','全普吉独一份的夜间海上体验：黄昏划进海蚀湖看日落、亲手放水灯，日落后看浮游生物在水里发蓝色荧光。','John Gray Sea Canoe 的招牌星光团：约 12:00 酒店接人，黄昏由专人划独木舟进 Hong 岛海蚀湖、船上晚餐，日落后亲手做水灯（krathong）放漂，再看发光浮游生物，约 21:30–22:00 回酒店（2026-10-24 tour 研究）。渠道价差大：US$118–156，经销页另有 ฿3,950 口径——订前比价、认官网。提前 1–2 周订；选它的当天上午留空别排重活动，回得晚、次日别排早团。本程定版未选：12-14 白天已排 Amazing Canoeing 纯玩团、晚间定版回 Dinso 休息且次日退房转场清迈，21:30–22:00 才回的星光团与之互斥、不双订；只有改主意放弃白天团时才作替补。','备选（定版未选，与 12-14 白天纯玩团二选一、不双订）：时间成本高，但夜间荧光海没有替代品；真要改选才提前 1–2 周订、订前比价认官网。'),A('蓝象 Blue Elephant 烹饪课','普吉','在普吉镇百年中葡老宅（原总督府邸）里上课：上午场先逛早市采购，再回老宅厨房做 4 道菜、在老宅餐厅吃掉自己的作品，环境本身就是半个景点。','Blue Elephant Phuket 烹饪课上午场：约 09:00 接人，先逛早市采购食材，回老宅厨房做 4 道菜并在老宅餐厅用餐，约 13:45 回酒店；฿3,296／人（2026-10-24 tour 研究）。TripAdvisor 带市场产品 5.0 分但仅 23 条、样本小，判定靠环境与课程结构、不吹口碑数字。离 Banyan Tree 与 Dinso 两家酒店均约 40 分钟车程。订法：走官网／Klook 拼班，避开 Cookly 私教版 US$323 的贵价渠道；提前 3–7 天订。','值得玩（陆上日选项）：与出海团互为雨天／体力备选，老宅环境是别家烹饪课没有的。'),A('芭东泰拳观赛','普吉','看泰拳礼仪与氛围的晚间填充：开场 Wai Kru 拜师舞＋传统乐队现场伴奏，接着 8 场真打；21:00 开打、看完回酒店近，不占白天。','芭东两家拳场观赛：Bangla Boxing Stadium 与 Patong Boxing Stadium，均约 21:00 开场、8 场约 2–2.5 小时；普通座 ฿1,500、擂台边 ฿1,800–1,900，Bangla 含免费 T 恤（2026-10-24 tour 研究）。场次按星期：Patong Boxing Stadium 周日休（12-14 周一可选它）；Bangla 渠道口径不一，订前以官方售票页为准（12-13 周日两口径都有场）。提前 1–3 天订座或现场买；白天出海回来太累就放弃、不硬撑。','值得玩（住芭东的晚间填充）：提前 1–3 天订座即可，不必早锁。'),A('137 Pillars 酒店烹饪课 Cook like a Thai Chef','清迈','本程定版已定的烹饪课：就在入住的 137 Pillars House 酒店内上课，下午场，不用往返城外农场，上完课直接回房休息——定版用它取代 Smile／Zabb E Lee 等外部烹饪课。','137 Pillars House（本程 12-15→12-18 入住酒店）酒店内烹饪课 Cook like a Thai Chef，本程定版排 12-17 下午：当天上午先走 Jungle Flight JF2 早班、中午咖喱面午餐，回酒店后上课，动线不出酒店、与「好酒店留出酒店时间」的定版口径一致。订前须知（证据边界）：该课的具体开课时间、时长、菜单、价格与预约方式在现有研究证据中未明确，不写死——须提前向酒店礼宾或酒店官网确认 12-17 下午场是否开课、是否需住客预约、是否含市场采买环节，确认后再锁定；若酒店课当天不开或订满，替补顺序看 Smile Organic Farm（评价量最大）与 Zabb E Lee（竹屋小班、中文友好）两条备选，不临时乱抓无证据的课。','已定版（12-17 下午）：提前向 137 Pillars 礼宾确认场次与价格并预订；确认不了就按替补顺序改订 Smile／Zabb，不叠加第二堂课。'),A('Smile Organic Farm 烹饪课','清迈','清迈烹饪课评价量天花板：市场采买到农场香草园，个人灶台从零做齐 5 大类菜，巨大有顶厨房天气无碍，课后可在农场泳池边休息。','Smile Organic Farm 半日烹饪课：09:00–14:00，含市场采买＋农场参观＋接送，约 US$28 起、可全素（2026-10-24 tour 研究）。口碑证据：Viator 5.0 分／20,758 条、Pelago 4.97 分／20,938 条，是全清迈烹饪课评价量最高的；但小红书零提及，证据全来自 TripAdvisor／Viator／Pelago。农场离古城约 45 分钟车程。注意：官网 ฿800 是旧收录价、订前复核现价；旺季提前 1–2 周，官网直订更便宜。定版口径（2026-10-24 用户采纳）：12-17 下午烹饪已改 137 Pillars 酒店内课（见「137 Pillars 酒店烹饪课」条目），本条目降为备选、不再作首选推荐。','备选（定版已改酒店内课）：本程 12-17 下午已按定版改上 137 Pillars 酒店内 Cook like a Thai Chef，本课只在酒店课订不到或特别想体验农场采买时才替补，不与酒店课同日叠加。'),A('Zabb E Lee 烹饪课','清迈','小红书体验派首选：竹屋厨房氛围感加老师会一点中文，一人选做 5 道菜吃到撑，含芒果糯米饭与泰奶。','Zabb E Lee Cooking School：竹屋厨房小班课，老师 Jess 热情、会一点中文（小红书实测帖口径，2026-10-24 tour 研究＋小红书复核）。฿1,200／人，评论称 11 月起涨到 ฿1,400——以官网为准；走官网邮件预订，竹屋档须提前订（有提前 1 天已订不到的实证）；线下办公室付费免 3% 手续费但需提前 2–3 天；古城 3 km 内免费接送。陪同票收费细则帖内未明确，下单时确认。对比提醒：小红书提及最多的奶奶厨房 Grandma’s Home 有接送被鸽／携程订位失联的实证避雷，要订走官网或请酒店代订。','备选（定版已改酒店内课）：本程 12-17 下午已按定版改上 137 Pillars 酒店内 Cook like a Thai Chef，本课只作替补——酒店课订不到、且更想要竹屋小班与中文氛围时才选，不与酒店课同日叠加。'),A('清迈泰拳体验课 Chiang Mai Muay Thai Gym','清迈','本程定版已定的上手体验课：古城内的 1 小时泰拳课，自己上场打——热身、基本动作、打沙袋到擂台轻对练，零基础也能跟完；不是看比赛，是 ENP 回城后的下午碎片项。','Chiang Mai Muay Thai Gym（古城内、步行可达，具体门牌现有证据未明确、下单页确认）：1 小时体验课，Klook 4.9 分（32–35 条、600+ 人订过）、约 US$29.49／人（2026-10-24 tour 研究，证据 hidden_files/tour-research/chiangmai-tours-2026-10-24.md 第 5 项）。流程经 Klook 实测评价坐实：热身、基本动作、打沙袋，最后上擂台轻对练（评价原话称内容很完整、非常推荐）。同价位备选：另一家初学者入门课 Klook 4.9 分（28 条、300+ 人订过）、US$15.55 起、可选私人教练；GetYourGuide 的 Tribal Muaythai 体验课 US$27.9 起、评价称教练会按每个人调整（2026-02）；Hong Thong Muay Thai（前冠军拳馆）Klook 4.7 分但仅 6 条评价、US$24.35，样本太薄只作参考、不作首选。订法：提前 1 天在 Klook 下单即可，不用早锁。本程定版排 12-16 约 15:00（ENP 半日上午约 14:00 回城后），ENP 回程延误就顺延或取消，别赶坏傍晚帕拉特寺到双龙寺的日落线。与普吉芭东泰拳观赛、曼谷 FITFAC／Watchara 的区别：这家是清迈古城内的上手体验课、就近不折腾。','已定版（12-16 下午）：提前 1 天在 Klook 订这家 1 小时课即可；回程延误就顺延或取消，不叠加第二堂运动课。'),A('Bangkok Kunsthalle《午夜之光》Bas Jan Ader 个展','曼谷','2026-10-14 至 2027-01-10 的当代艺术个展，正好覆盖曼谷 12-18／19 两天的白天时段。','Bangkok Kunsthalle 呈现荷兰观念艺术家 Bas Jan Ader 个展《午夜之光》（Bright at Midnight），展出其 1970–1975 年的三件代表作，展场本身是尚未完工的建筑空间，看展体验一半在作品、一半在空间。展期 2026-10-14 至 2027-01-10 已帖级坐实（策展人友人发帖正文＋海报图双重确认，证据见 round418）。门票价格、开放时间、是否需要预约帖内均未明确——另有旧帖标题称该馆展览免费，但未核实，临行查官网或到现场确认，不按免费写死。','值得玩：档期与行程严丝合缝，适合 12-18 或 12-19 白天用 1–2 小时填充，夫妻二人时段顺路看，不占主活动时段。'),A('Lannatique 一期 · Lanna Garden','清迈','长康路夜市旁的新开综合体第一阶段：号称泰北最长的弧面 3D LED 屏是地标，米其林主厨餐厅 Akantuka 已开业，逛夜市顺路连看。','Lannatique 第一阶段（官方名 Lanna Garden，Kalare 地块、长康路夜市旁）已正式开放——小红书开业帖帖级坐实（作者 Chu，2026-08-29，96 赞／104 藏，13 张实拍，2026-10-24 round410 复核）：弧面 3D LED 屏已点亮；米其林主厨餐厅 Akantuka（设在郑和故居 The Zheng He Heritage House 内）已开业；Starganza Live! 卡巴莱秀已推出；已开业的还有 Minimal 咖啡、Moonsoon 茶与伴手礼店；Panpuri 水疗尚未开放。未明确项（帖内未写、临行复核）：Starganza 演出日／场次／票价、Akantuka 营业时间／人均／是否需预约、Lanna Garden 开放时间。位置与 137 Pillars 同侧、离瓦洛洛与周日步行街动线近，任一晚饭后顺路逛即可、不专程。','值得玩（顺路项）：免费逛加看 LED 屏，与长康路夜市同晚打包；Akantuka 作备选晚餐候选（先复核预约）。'),A('古树公园 Changthong Heritage Park','清迈','成片古树环绕的治愈公园：发现轮最强帖（1,028 赞／1,024 藏）称比清迈大学更治愈，12 月旱季正宜，入口苔藓古树小径是招牌机位。','Changthong Heritage Park：成片古树与苔藓小径，19:00 闭园、最佳光线约 18:00 蓝调时分（2026-10-21 发现第四轮帖级证据）。门票价原帖未明确、按现场为准不预估。离古城有距离、需打车前往（原帖称打车比想象中容易）。下午半日量级：若同日安排泰北菜正餐 Huen Muan Jai，选它的午餐场再来公园，别两头赶。','值得玩（下午候选）：纯逛型、无需提前订，现场买票即可。'),A('Seasons of Neighbors','清迈','昌康路 2026-10-10 刚开业的泰国本土创意品牌集合店，11:00–19:00，就在长康路夜市同一片区，逛夜市前顺路先逛它。','Seasons of Neighbors 在昌康路 Chang Klan Road（即长康路），2026-10-10 开业的泰国本土创意品牌集合店，营业 11:00–19:00（证据：官方号开业公告帖，2026-10-02 发帖、无评论；2026-10-21 发现第四轮）。与长康路夜市同片区：去长康路线时先逛它（19:00 关门，别拖到夜市逛完再去）、再接夜市；去清迈大学夜市方向就别硬绕，留到路过昌康路时再逛。目前只有开业公告、无食客口碑帖，当顺路一站看、别专程。','值得玩（顺路项）：纯逛型、无需预订，19:00 关门是唯一时间约束。'),A('FITFAC 泰拳私教','曼谷','1 对 1 按体能量身的泰拳私教：空调馆不遭罪、课后送泰拳短裤；TripAdvisor 有 61 岁零基础完整跟完的实证。','FITFAC Muay Thai 私教课 60 分钟：官网 ฿1,790／人、KKday US$53.02——渠道价差大，走官网／KKday（2026-10-24 tour 研究）。Ploenchit 有分店、离 Park Hyatt 与 Rosewood 两家酒店近；研究称含酒店接送（接送范围下单时确认）；某分店周五 13:00 后才开课的口径各店不一，以下单选店为准。小红书无帖，证据来自 TripAdvisor。提前几天订即可。','值得玩（轻量填充）：想私教定制选它，想便宜热闹看 Watchara 条目，二选一。'),A('Watchara 泰拳团课','曼谷','小红书零基础首选：热身到基础动作到打靶到体能完整一节，暴汗解压、教练耐心，氛围不紧张。','Watchara MuayThai Gym（Sukhumvit）：团课制，小红书实测帖口径（2026-10-24 tour 研究＋小红书复核）——注意封面写一对一、实为团课（作者评论澄清）。价格：作者口径人均约 90（币种帖内未明、不写死）；面级口径团课约 ฿400–700／人、私教 ฿800–1,500，下单页确认。手套可现场租。提前几天订即可。','值得玩（与 FITFAC 二选一）：便宜热闹选它，私教定制选 FITFAC。'),A('Rajadamnern 泰拳场 · RWS','曼谷','曼谷泰拳观赛天花板：1945 年老牌拳场，翻新后 360 度穹顶 LED 巨幕；周六 RWS 旗舰场是国际拳手阵容。','Rajadamnern Stadium 的 Rajadamnern World Series（RWS）：18:00 入场、19:00 开赛。票档经小红书核实（2026-10-24 tour 研究＋小红书复核）：外圈 ฿1,000／Leo ฿1,500／Club ฿1,800／Ringside ฿2,500／总统包厢 ฿3,500。排期提示：本行程 12-18（周五）晚与已订 Le Du 冲突；12-19（周六）旗舰场只作 Sorn 的备胎——11-25 Sorn 放号后再决策，订上 Sorn 就不去、不双订；真要订趁早，周六场最先售罄。','值得玩（仅 Sorn 备胎）：决策点在 11-25 Sorn 放号之后，落空尽快订。'),A('Tingly Thai 烹饪课','曼谷','曼谷烹饪首选：只有上午班才有的 Wat Khaek 市场采购环节——跟老师逛市场认食材，再自制咖喱酱做 4 道菜、带走食谱书。','Tingly Thai Cooking School 上午班：08:30–12:00、含市场采购，小班不超过 12 人，TripAdvisor 5.0 分／699 条、老师 Cho／Song 被点名夸（2026-10-24 tour 研究）。Viator 约 US$36.52–42.10／人；自行到校集合、不含接送；提前 1–2 周订，24 小时前免费取消。避雷：下午／晚班不含市场采购、价值打折，别订错班次。','值得玩（曼谷烹饪首选）：上午半天搞定，下午晚上都不耽误。'),A('圣淘沙缆车 SkyPass','新加坡','跨海缆车进圣淘沙，行程本身就是景点：高空看港湾与岛景，推车可直接上，不用换乘折腾娃。','Singapore Cable Car SkyPass（花柏山线＋圣淘沙线）：Headout S$32.90、0–3 岁免费（2026-10-24 tour 研究）。从港湾站 HarbourFront 上车，别从花柏山站爬陡坡；两线须同日用完；末班登车 21:30；票多不可取消，去前 1 天订即可。SkyOrb 玻璃底升级约 S$15、多评不值，别加。作进出岛方式与圣淘沙日拼在一起才划算（或照旧 Sentosa Express S$4 进岛）。','值得玩（作交通方式）：不单独成团，拼圣淘沙日用。'),A('娘惹博物馆 Peranakan Museum','新加坡','9 个展厅的国家级馆，一次看懂娘惹婚俗、服饰与家居；每天开、免预约、无障碍，是全家行程里最稳的弹性填充。','Peranakan Museum（亚美尼亚街）：国家级娘惹文化馆，免费义工讲解先到先得，节奏自控（45 分钟到 2 小时）；10:00–19:00、周五至 21:00，闭馆前 30 分钟停入；6 岁以下免费（2026-10-24 tour 研究）。票价两源冲突（常设展 S$12 与全通票 S$18 两说），以官网为准。推车／轮椅无障碍，适合带娃与长辈的半日弹性项。','值得玩（娘惹主题保底项）：免预约、现场买票即可。'),...SEOUL_ATTRACTIONS
];
export const shopping={"曼谷":"ICONSIAM、暹罗商圈、恰图恰；买泰丝、香氛、设计杂货。","清迈":"瓦洛洛市场、宁曼路、Baan Kang Wat；买泰北香肠、木雕与棉织品。","普吉":"老镇周日步行街、Central Phuket；买锡器、腰果与海岛度假品。","槟城":"乔治市骑楼店、Gurney Plaza；买豆蔻制品、白咖啡与娘惹工艺。","吉隆坡":"Pavilion、Suria KLCC、中央市场；买锡器、巴迪布与本地设计。","胡志明市":"同起街、Tan Dinh 或 Binh Tay；滨城市场只看建筑，不建议购物。","富国岛":"阳东镇正规商店；夜市先问价，鱼露与易碎品托运前二次密封。","新加坡":"乌节路、Marina Bay Sands、Jewel；集中采购国际品牌与娘惹手信。","首尔":"明洞、弘大、圣水洞；买K-beauty、韩式小吃与设计师品牌。"};

/* 购物推荐：按城市的结构化深指南（2026-09-27 研究整理）
   malls=值得逛的商场/市场+特色；souvenirs=伴手礼/纪念品（star=最值得买）；
   tips=退税/砍价/托运等实操贴士。旧 shopping 一句话版保留给行程日卡用。 */
export interface ShoppingEntry{ name:string; note:string; star?:boolean }
/** 商场/市场详细信息：位置、照片、详细评价（2026-09-27 购物改版） */
export interface MallDetail{
 name:string; area:string; address:string; hours:string;
 transport?:string; // 交通方式
 mapUrl?:string; // Google Maps 导航链接
 officialUrl?:string; // 官网链接
 positioning:string; highlights:string[]; review:string; tips:string;
 sources?:string[]; // 可复现来源链接
 updatedAt?:string; // 查询日期，如 2026-09-27
 photos?:{url:string; source:string}[]; // 照片组：直链+来源页
 photo?:string; photoSource?:string; // 兼容旧单图字段
}
export interface ShoppingGuide{ lead:string; malls:MallDetail[]; souvenirs:ShoppingEntry[]; tips:string[] }
/** 商场详情深链锚点 id：地图 popup 链接与 MallCard 共用，保证两端一致 */
export function mallAnchorId(name:string):string{ return "mall-"+encodeURIComponent(name); }
