malls:[
{name:"乔治市骑楼店",area:"乔治市老城 UNESCO 世遗核心区（Armenian Street / Beach Street / Cannon Street / Pitt Street 一带）",address:"Lebuh Armenian, George Town, 10200 Penang, Malaysia",hours:"沿街店铺多为每日 10:00–22:00（各店不同）；Armenian Street Fair 每周六傍晚举行；街道全天可步行游览",mapUrl:"https://www.google.com/maps/search/?api=1&query=%E4%B9%94%E6%B2%BB%E5%B8%82%E9%AA%91%E6%A5%BC%E5%BA%97%20Lebuh%20Armenian%2C%20George%20Town%2C%2010200%20Penang%2C%20Malaysia",officialUrl:"",positioning:"乔治市世遗老城的骑楼老街购物区，街头壁画、娘惹手信与文创小店的集合地，边逛边拍的代表街区。",highlights:["Armenian Street 壁画群（姐弟共骑单车等）与彩色雨伞巷，骑楼建筑本身就是打卡点","娘惹与文创手信店集中：Loka Made 纪念邮戳明信片、14 Living Story、珠绣鞋与手工首饰店","每周六傍晚 Armenian Street Fair 街头市集，本地手作与街头表演"],review:"适合喜欢边走边逛、买有槟城特色明信片、峇迪小物、娘惹饰品的游客；优点是氛围好、店铺密集、多数明码标价；短板是游客区属性强、部分商品溢价明显，周末人多且天气炎热，纯购物效率不如商场。",tips:"选工作日上午去，人少好逛好拍照；周六傍晚可顺逛街头市集；骑楼小店先比价再买，同类手信多家店都有，明码标价但可小幅议价",sources:["https://wanderlog.com/place/details/530625","https://airial.travel/attractions/malaysia/george-town/armenian-street-and-surrounding-areas-george-town-58zFqPES","https://evendo.com/locations/malaysia/penang/best-shops"],updatedAt:"2026-09-27",photos:[]},
{name:"Gurney Plaza",area:"Gurney Drive 海滨长廊商圈（乔治市老城西北约 3 公里）",address:"170, Gurney Drive (Persiaran Gurney), George Town, Penang 10250, Malaysia",hours:"每日 10:00–22:00",mapUrl:"https://www.google.com/maps/search/?api=1&query=Gurney%20Plaza%20170%2C%20Gurney%20Drive%20%28Persiaran%20Gurney%29%2C%20George%20Town%2C%20Penang%2010250%2C%20Malaysia",officialUrl:"https://www.gurneyplaza.com.my/",positioning:"槟城岛地标型高端生活方式商场，400 多家店铺、九层楼，岛上品牌最全的一站式购物点。",highlights:["Parkson 百货、GSC 影院、senQ 电器等主力店齐全，国际品牌与本地品牌兼顾","餐饮选择多，从美食广场到海景餐厅，逛累了直接吃饭看电影","Tripadvisor 4.1 分（626 条评价），沿海位置傍晚可顺逛 Gurney 海滨步道"],review:"适合想一次买齐服装、美妆、电子产品并顺带娱乐的游客；优点是品牌全、冷气足、餐饮多；短板是整体价格偏高（被列为 expensive 级别），周末停车难，离老城区需打车约 10 分钟，不顺路时不必硬挤行程。",tips:"用 Grab 往返老城区约 10 分钟，避开周末下午的停车高峰；出发前先查官网 gurneyplaza.com.my 的促销季信息，赶上大促再专程去",sources:["https://gurneyplaza.com.my/","https://wanderlog.com/place/details/74961","https://www.tripadvisor.in/Attraction_Review-g298303-d2303531-Reviews-or20-Gurney_Plaza-George_Town_Penang_Island_Penang.html"],updatedAt:"2026-09-27",photos:[]}],
